import type { ContentCatalogue } from '../content'

export const ES_SUMMARIES: ContentCatalogue = {
  "summary.1Chr.authorship": { fp: "13krv4", text: "Anónimo («el Cronista»), posexílico." },
  "summary.1Chr.contents": { fp: "17hjh8n", text: "Genealogías desde Adán, y después un relato del reinado de David centrado en el templo." },
  "summary.1Chr.context": { fp: "b0olxb", text: "Escrito para la comunidad restaurada, a fin de reafirmar su identidad, su culto y su esperanza davídica." },
  "summary.1Chr.nt": { fp: "6567tm", text: "Su foco genealógico y davídico está detrás de las genealogías neotestamentarias y de la esperanza mesiánica." },
  "summary.1Chr.significance": { fp: "z0q7r7", text: "Crónicas insiste en el culto debido, en el pacto davídico y en el propósito continuado de Dios para su pueblo después del destierro." },
  "summary.1Esd.authorship": { fp: "a40p5o", text: "El compilador es desconocido. El libro es una versión griega que se traslapa ampliamente con 2 Crónicas, Esdras y Nehemías, pero los especialistas discuten si conserva una forma más antigua de ese material o si lo reelabora posteriormente." },
  "summary.1Esd.contents": { fp: "fr5bpl", text: "Además de volver a contar la restauración de época persa, añade un relato único: tres guardaespaldas debaten qué es lo más fuerte del mundo (el vino, los reyes o las mujeres) antes de que uno sostenga que vence «la verdad», con lo que Zorobabel gana el favor real para reconstruir Jerusalén." },
  "summary.1Esd.context": { fp: "1wauraj", text: "Traducido o compuesto probablemente en el siglo II a. C., refleja el interés judío sostenido por la historia de la reconstrucción del Templo tras el destierro babilónico, entendida como el momento fundacional del culto del Segundo Templo." },
  "summary.1Esd.nt": { fp: "mup7ar", text: "Sus temas de restauración y reconstrucción resuenan con las esperanzas de renovación del Nuevo Testamento, aunque allí no se lo cita directamente. Su condición canónica varía: los ortodoxos lo aceptan, los católicos lo sitúan en un apéndice y los protestantes lo consideran apócrifo." },
  "summary.1Esd.significance": { fp: "1ghxr2o", text: "El libro presenta a reyes paganos como Ciro y Darío en calidad de instrumentos de los que Dios se sirve para restaurar el Templo de Israel, y subraya que hasta los gobernantes extranjeros sirven al plan de Dios, junto con el mensaje de que la verdad es el poder más grande y más duradero." },
  "summary.1Kgs.authorship": { fp: "6cwnpo", text: "Anónimo; parte de la historia deuteronomista." },
  "summary.1Kgs.contents": { fp: "1dxshdm", text: "El reinado de Salomón y su templo, la división del reino, y los ministerios de los profetas Elías y Eliseo." },
  "summary.1Kgs.context": { fp: "1ome43t", text: "Parte de los Libros de los Reinados griegos." },
  "summary.1Kgs.nt": { fp: "h1sxa", text: "Jesús apela a Salomón y a Elías, y el tema del templo recorre los Evangelios y Hechos." },
  "summary.1Kgs.significance": { fp: "15c078b", text: "Mide a los reyes por su fidelidad al pacto y muestra el templo como el lugar del nombre de Dios, mientras los profetas confrontan la apostasía." },
  "summary.1Macc.authorship": { fp: "bg7xjn", text: "El autor es desconocido, pero fue casi con seguridad un escritor judío simpatizante de la familia real asmonea, que escribió en hebreo (solo se conserva la traducción griega)." },
  "summary.1Macc.contents": { fp: "hkzdji", text: "El libro narra la persecución bajo Antíoco IV, la rebelión victoriosa encabezada por Judas Macabeo y sus hermanos, la rededicación del Templo de Jerusalén (el origen de Janucá) y el ascenso de la dinastía asmonea." },
  "summary.1Macc.context": { fp: "111uyh7", text: "Escrito a fines del siglo II a. C., probablemente durante el reinado de Juan Hircano o poco después, el libro abarca la rebelión macabea contra el dominio griego desde alrededor del 175 hasta el 134 a. C." },
  "summary.1Macc.nt": { fp: "hy4661", text: "El libro aporta el trasfondo histórico imprescindible del mundo judío en el que nacería Jesús, incluidos grupos y tensiones que el Nuevo Testamento da por conocidos. Es Escritura para católicos y ortodoxos, y queda excluido de las Biblias hebrea y protestante, pese a su gran valor como historia." },
  "summary.1Macc.significance": { fp: "1sy690g", text: "A diferencia de muchos otros textos judíos, 1 Macabeos rara vez menciona a Dios de manera directa; en su lugar muestra la providencia divina obrando en silencio a través del celo heroico y la fidelidad de la familia macabea, probablemente para respaldar la legitimidad política de los asmoneos." },
  "summary.1Sam.authorship": { fp: "16q80xp", text: "Anónimo; Samuel y Reyes forman una historia continua." },
  "summary.1Sam.contents": { fp: "oh1jk7", text: "Desde Samuel y los últimos jueces hasta el ascenso y la caída de Saúl y la aparición de David." },
  "summary.1Sam.context": { fp: "1s1l1mu", text: "Parte de los «Libros de los Reinados» griegos (1–4 Reinados) en la Septuaginta." },
  "summary.1Sam.nt": { fp: "nhj9ad", text: "La unción de David y la promesa ligada a su linaje fundamentan la presentación neotestamentaria de Jesús como Hijo de David y Mesías." },
  "summary.1Sam.significance": { fp: "1fk4x6p", text: "Traza los orígenes de la monarquía en Israel bajo la soberanía de Dios, y contrasta al rechazado Saúl con el elegido David." },
  "summary.1enoch.authorship": { fp: "hhpdge", text: "Un apocalipsis compuesto atribuido a Enoc, escrito en realidad por varios autores judíos anónimos entre aproximadamente el siglo III a. C. y el I d. C.; se conserva completo solo en etiópico." },
  "summary.1enoch.contents": { fp: "221r2b", text: "Cinco partes que incluyen la caída de los vigilantes y el origen del mal, saberes astronómicos y calendáricos, visiones oníricas de la historia, las «Similitudes» con su Hijo del Hombre celestial, y las exhortaciones de Enoc." },
  "summary.1enoch.context": { fp: "1nmw05g", text: "Sus secciones crecieron a lo largo de siglos dentro del judaísmo apocalíptico; se hallaron partes en Qumrán, lo que muestra su importancia en los círculos sectarios del Segundo Templo." },
  "summary.1enoch.nt": { fp: "1lrp5qe", text: "Su Hijo del Hombre, sus escenas de juicio y su angelología forman un trasfondo crucial para la escatología neotestamentaria; Judas 14–15 cita 1 Enoc directamente." },
  "summary.1enoch.significance": { fp: "o7u0t2", text: "Desarrolla ideas influyentes sobre el origen del mal, las jerarquías angélicas, el juicio final, la resurrección y una figura celestial y preexistente de redentor." },
  "summary.2Chr.authorship": { fp: "13krv4", text: "Anónimo («el Cronista»), posexílico." },
  "summary.2Chr.contents": { fp: "16oufa4", text: "El templo de Salomón y los reyes de Judá, hasta el destierro y el edicto de Ciro que permite el regreso." },
  "summary.2Chr.context": { fp: "pu11we", text: "Dirigido a la comunidad posexílica que reconstruía su vida en torno al templo." },
  "summary.2Chr.nt": { fp: "jm6gkl", text: "Su esperanza final de restauración y de culto reconstruido enmarca la expectativa que el Nuevo Testamento ve cumplida en Cristo, el templo verdadero." },
  "summary.2Chr.significance": { fp: "7dmem0", text: "Realza el templo y el culto de todo corazón, y termina con la nota de esperanza del regreso y la restauración." },
  "summary.2Kgs.authorship": { fp: "1s718dk", text: "Anónimo; continúa 1 Reyes." },
  "summary.2Kgs.contents": { fp: "1wxkapj", text: "La decadencia paralela de Israel y de Judá hasta la caída de Samaria y el destierro babilónico." },
  "summary.2Kgs.context": { fp: "1ome43t", text: "Parte de los Libros de los Reinados griegos." },
  "summary.2Kgs.nt": { fp: "xgo6oc", text: "El destierro que narra prepara el marco neotestamentario de una restauración todavía esperada y cumplida en Cristo (cf. Mateo 1)." },
  "summary.2Kgs.significance": { fp: "iazkhh", text: "Presenta el destierro como consecuencia del quebrantamiento persistente del pacto, y deja aun así un hilo de esperanza en el linaje davídico sobreviviente." },
  "summary.2Macc.authorship": { fp: "57xpu4", text: "El libro dice ser el resumen de una historia más extensa, hoy perdida, de un tal Jasón de Cirene; se desconoce quién fue el editor que hizo ese resumen." },
  "summary.2Macc.contents": { fp: "w8ph17", text: "Abarca un período más breve que 1 Macabeos: se centra en la persecución bajo Antíoco IV y en las primeras victorias de Judas Macabeo, e incluye el célebre relato de una madre y sus siete hijos martirizados por negarse a quebrantar la ley judía." },
  "summary.2Macc.context": { fp: "a1ja1b", text: "Compuesto en griego, probablemente a mediados o fines del siglo II a. C. para los judíos que vivían en Egipto, con un estilo dramático y emotivo propio de la historiografía griega, y no con el estilo llano de 1 Macabeos." },
  "summary.2Macc.nt": { fp: "z1irwj", text: "Su teología del sufrimiento de los mártires en beneficio de toda la nación moldeó fuertemente la comprensión cristiana primitiva de la muerte de Jesús como sacrificio por otros. Es canónico para católicos y ortodoxos, y queda excluido de las Biblias hebrea y protestante." },
  "summary.2Macc.significance": { fp: "lii0zj", text: "Este libro es la declaración clara más antigua de la literatura judía sobre la resurrección corporal como recompensa de los mártires fieles. Introduce además la idea de orar por los muertos, importante más tarde en la enseñanza católica sobre el purgatorio." },
  "summary.2Sam.authorship": { fp: "fzlnmd", text: "Anónimo; continúa 1 Samuel." },
  "summary.2Sam.contents": { fp: "19ykj44", text: "El reinado de David: sus triunfos, su pecado con Betsabé y los conflictos dentro de su casa." },
  "summary.2Sam.context": { fp: "1ome43t", text: "Parte de los Libros de los Reinados griegos." },
  "summary.2Sam.nt": { fp: "9hgcnq", text: "La promesa de una dinastía davídica eterna se cumple, en la lectura del Nuevo Testamento, en Jesús el Mesías (Hechos 2; Romanos 1)." },
  "summary.2Sam.significance": { fp: "nmei3r", text: "El pacto davídico (2 Samuel 7), que promete a David un trono eterno, se convierte en un gozne de la esperanza bíblica." },
  "summary.2baruch.authorship": { fp: "17nlntk", text: "Un apocalipsis judío atribuido a Baruc, el escriba de Jeremías; escrito después del año 70 d. C. y conservado en siríaco." },
  "summary.2baruch.contents": { fp: "1q9al0c", text: "En respuesta a la caída de Jerusalén, Baruc recibe visiones y dialoga con Dios sobre el sentido del sufrimiento, el cuerpo de la resurrección, el Mesías venidero y el consuelo duradero de la Ley." },
  "summary.2baruch.context": { fp: "9ag464", text: "Como 4 Esdras, responde a la destrucción de Jerusalén por Roma y reflexiona sobre el pacto, el sufrimiento y la esperanza." },
  "summary.2baruch.nt": { fp: "ljwpw5", text: "Su estructura de dos eras, su esperanza en la resurrección y su mesianismo corren muy en paralelo con Pablo y con Apocalipsis, e iluminan la teodicea judía y cristiana posterior al año 70." },
  "summary.2baruch.significance": { fp: "3z43vv", text: "Afirma que la Ley perdura aun cuando el templo ya no está, y que Dios resucitará a los muertos y vindicará a los justos en la era venidera." },
  "summary.2enoch.authorship": { fp: "jfu3qd", text: "Un apocalipsis atribuido a Enoc, de origen judío discutido (posiblemente del siglo I d. C.), conservado en eslavo." },
  "summary.2enoch.contents": { fp: "kp803l", text: "A Enoc se lo lleva a través de los (siete o diez) cielos, se le muestran sus secretos, Dios lo instruye sobre la creación y la vida moral, y regresa a enseñar a sus hijos antes de su ascenso definitivo." },
  "summary.2enoch.context": { fp: "9ysfpc", text: "Se sitúa en la tradición enóquica y reelabora motivos de ascenso celestial para un público posterior." },
  "summary.2enoch.nt": { fp: "1xm6vo", text: "Su ascenso celestial, sus recorridos cósmicos y su dualismo ético ofrecen trasfondo comparativo para las visiones neotestamentarias (2 Corintios 12; Apocalipsis)." },
  "summary.2enoch.significance": { fp: "cmw28o", text: "Subraya el ordenamiento divino de la creación, la recompensa de los justos y el castigo de los malvados, y una instrucción ética arraigada en la visión celestial." },
  "summary.2esdras.authorship": { fp: "1twnke6", text: "Un apocalipsis compuesto (llamado también 4 Esdras) cuyo núcleo judío central (caps. 3–14) se escribió en hebreo o arameo hacia el año 100 d. C., y más tarde quedó envuelto en añadidos cristianos (caps. 1–2 y 15–16); se conserva sobre todo en latín." },
  "summary.2esdras.contents": { fp: "fxthke", text: "Esdras interroga a Dios sobre el sufrimiento de Israel y la justicia del mundo a lo largo de siete visiones y diálogos con el ángel Uriel; se lo conduce de la protesta a la esperanza de una era venidera, de un libertador mesiánico preexistente, de la resurrección y del juicio final, y por último se le encarga restaurar las Escrituras." },
  "summary.2esdras.context": { fp: "gxdf5e", text: "El núcleo judío responde a la destrucción de Jerusalén por Roma en el año 70, y forcejea —como 2 Baruc— con la pregunta de cómo un Dios justo pudo permitir que su ciudad y su pueblo fueran aplastados por los malvados." },
  "summary.2esdras.nt": { fp: "6fsgvm", text: "Su marco de las dos eras, su expectativa mesiánica y su lenguaje sobre el «Altísimo», el juicio venidero y los pocos que se salvan iluminan el mundo apocalíptico de ideas que comparte con Pablo, con Apocalipsis y con el apocalipsis sinóptico." },
  "summary.2esdras.significance": { fp: "1i5x7lg", text: "El libro afronta de frente la teodicea: la era presente está corrompida y condenada, pero viene una era nueva en la que Dios vindicará a los justos. Desarrolla ideas ricas sobre las dos eras, el Mesías y el destino del alma después de la muerte." },
  "summary.3Macc.authorship": { fp: "1rdw1vb", text: "Pese a su título, este libro no tiene nada que ver con la rebelión macabea. Su autor, un judío alejandrino, es desconocido." },
  "summary.3Macc.contents": { fp: "t2ieqv", text: "El relato cuenta cómo Ptolomeo IV intenta entrar en el recinto más sagrado del Templo de Jerusalén y Dios se lo impide; entonces se venga de los judíos de Alejandría e incluso intenta matarlos con elefantes ebrios en un estadio, plan que fracasa cuando Dios interviene." },
  "summary.3Macc.context": { fp: "jxrzhz", text: "Ambientado dos generaciones antes de los macabeos, bajo Ptolomeo IV (221–204 a. C.), se escribió probablemente a fines del siglo II o en el I a. C., y refleja tensiones reales que los judíos de Alejandría, en Egipto, enfrentaban bajo el dominio griego o romano." },
  "summary.3Macc.nt": { fp: "1yyyoj3", text: "Como Ester y Daniel, pertenece al género de la «liberación de la persecución», familiar para los primeros lectores cristianos. Es Escritura para los cristianos ortodoxos orientales, y queda excluido de las Biblias católica y protestante." },
  "summary.3Macc.significance": { fp: "cccy12", text: "El libro subraya que Dios sigue siendo fiel a los judíos aun fuera de la tierra de Israel, que la oración es poderosa y que quienes persiguen al pueblo de Dios serán a su vez castigados." },
  "summary.3baruch.authorship": { fp: "1v1gd2h", text: "Un apocalipsis griego atribuido a Baruc, de origen judío con edición cristiana, de los primeros siglos de nuestra era." },
  "summary.3baruch.contents": { fp: "huyv47", text: "Afligido por Jerusalén, Baruc es guiado por un ángel a través de cinco cielos, y contempla maravillas cósmicas y el destino de los justos y de los malvados." },
  "summary.3baruch.context": { fp: "1a2ij8k", text: "Pertenece a los apocalipsis de «viaje celestial» que florecieron en los círculos del Segundo Templo y del cristianismo primitivo." },
  "summary.3baruch.nt": { fp: "16i7z9h", text: "Su recorrido celestial guiado y su revelación del destino de las almas corren en paralelo con elementos apocalípticos del Nuevo Testamento y de la literatura visionaria cristiana primitiva." },
  "summary.3baruch.significance": { fp: "wf28dk", text: "Consuela el duelo por Jerusalén con una visión del cosmos ordenado por Dios y de su justicia venidera." },
  "summary.4Macc.authorship": { fp: "jnc3ia", text: "El autor es un escritor judío desconocido de la diáspora, con alta formación en la retórica filosófica griega, sobre todo en la ética estoica." },
  "summary.4Macc.contents": { fp: "1cvh1ks", text: "El libro sostiene que «la razón piadosa domina sobre las pasiones», y lo demuestra mediante un relato detallado de los martirios del anciano Eleazar y de una madre con sus siete hijos bajo Antíoco IV, ampliando la historia de 2 Macabeos." },
  "summary.4Macc.context": { fp: "2lp0it", text: "La mayoría de los especialistas lo fecha entre comienzos y mediados del siglo I d. C., posiblemente por la época en que el emperador Calígula intentó profanar el Templo de Jerusalén, en el año 40." },
  "summary.4Macc.nt": { fp: "78yx76", text: "Su vocabulario de martirio expiatorio ofrece un trasfondo valioso para entender cómo los primeros cristianos explicaron el significado salvífico de la muerte de Jesús (compárese Romanos 3:25). Es canónico solo para los cristianos ortodoxos georgianos." },
  "summary.4Macc.significance": { fp: "r8pu41", text: "Describe la muerte de los mártires con palabras como «rescate» y «sacrificio de expiación», un lenguaje llamativamente cercano al modo en que el Nuevo Testamento describe el sentido de la muerte de Jesús, y afirma la inmortalidad personal de los justos." },
  "summary.Amos.authorship": { fp: "ms767s", text: "Amós de Tecoa, profeta y pastor del siglo VIII." },
  "summary.Amos.contents": { fp: "qepbq2", text: "Oráculos cortantes contra la injusticia social y el culto vacío, con la exigencia de que «corra el juicio como las aguas», y una nota final de restauración." },
  "summary.Amos.context": { fp: "13boaf8", text: "Profetiza contra el reino del norte, próspero pero injusto, antes de su caída." },
  "summary.Amos.nt": { fp: "16aawkh", text: "Santiago cita la promesa de Amós de reconstruir el tabernáculo caído de David como cumplida en la inclusión de los gentiles (Hechos 15)." },
  "summary.Amos.significance": { fp: "1u68ugc", text: "Amós insiste en que Dios exige justicia y rectitud, no un rito divorciado de la ética." },
  "summary.Bar.authorship": { fp: "1or94oh", text: "El libro dice haber sido escrito por Baruc, el escriba del profeta Jeremías, pero los especialistas coinciden en que es un seudónimo. En realidad es la unión de al menos tres piezas distintas, reunidas por un editor desconocido." },
  "summary.Bar.contents": { fp: "8jd4zq", text: "El libro contiene una confesión comunitaria de pecado, un poema que alaba a la Sabiduría identificándola con la Torá (muy parecido a Sirácida 24) y un poema de consuelo dirigido a Jerusalén, personificada como una madre que llora." },
  "summary.Bar.context": { fp: "hyoyo7", text: "Las fechas de sus partes van desde el período persa hasta después del año 70 d. C., pero la mayoría de los especialistas piensa que se ensambló en torno a la crisis macabea (mediados del siglo II a. C.), usando el recuerdo del destierro babilónico para hablar a una crisis nacional posterior." },
  "summary.Bar.nt": { fp: "1843ak9", text: "Los temas de confesión nacional y restauración de Baruc corren en paralelo con las ideas neotestamentarias sobre el arrepentimiento y la esperanza, aunque allí no se lo cita directamente. Se incluye en las Biblias católica y ortodoxa, y queda excluido de los cánones hebreo y protestante." },
  "summary.Bar.significance": { fp: "tawowk", text: "Baruc interpreta el destierro como castigo justo por quebrantar el pacto y llama a Israel a confesar su pecado, con una esperanza de restauración fundada en la posesión exclusiva que Israel tiene de la Sabiduría hecha Torá, siguiendo el patrón clásico de pecado, castigo, arrepentimiento y restauración." },
  "summary.Bel.authorship": { fp: "1e6hsyn", text: "Estos dos relatos satíricos anónimos están agregados al final de Daniel y probablemente se compusieron en su origen en una lengua semítica." },
  "summary.Bel.contents": { fp: "vh8nhj", text: "En el primer relato, Daniel demuestra que los sacerdotes del ídolo Bel se comían en secreto las ofrendas. En el segundo, mata a una serpiente que era adorada y lo echan a un foso de leones, donde sobrevive ileso y el profeta Habacuc lo alimenta." },
  "summary.Bel.context": { fp: "1br0y6h", text: "Suelen fecharse en el siglo II a. C., junto con el resto del material de Daniel, en una época en que los judíos eran tentados o presionados a aceptar prácticas religiosas extranjeras." },
  "summary.Bel.nt": { fp: "19t8fw6", text: "Estos relatos continúan el patrón bíblico de liberación milagrosa que se ve en Daniel 3 y 6, patrón que reaparece en los relatos neotestamentarios de rescate (como la fuga de Pedro de la cárcel en Hechos). Es canónico para católicos y ortodoxos, y excluido en otras tradiciones." },
  "summary.Bel.significance": { fp: "9zdfht", text: "Ambos relatos se burlan de la impotencia y el fraude del culto pagano, y a la vez muestran al Dios verdadero protegiendo activamente a su siervo fiel, con lo que refuerzan el mensaje de que la lealtad a Dios trae liberación aun en peligro de muerte." },
  "summary.DanLXX.authorship": { fp: "19hinvi", text: "La traducción del griego antiguo de Daniel (distinta de la versión de Teodoción, posterior y de uso más extendido), que vierte el libro hebreo-arameo del siglo II a. C. junto con sus adiciones griegas." },
  "summary.DanLXX.contents": { fp: "1e9i6p4", text: "Los relatos cortesanos de Daniel y sus compañeros bajo reyes babilonios y persas, seguidos de visiones apocalípticas de imperios sucesivos y del fin, más las adiciones: la Oración de Azarías y el Cántico de los tres jóvenes, Susana, y Bel y el dragón." },
  "summary.DanLXX.context": { fp: "12ja7ou", text: "El Daniel hebreo-arameo alcanzó su forma final durante la persecución de Antíoco IV Epífanes (c. 167–164 a. C.); el griego antiguo circuló en el judaísmo de habla griega antes de quedar en buena medida desplazado por la revisión de Teodoción." },
  "summary.DanLXX.nt": { fp: "1cuylh", text: "Su «uno como hijo de hombre», la resurrección de los muertos y su esquema de reinos mundiales moldearon hondamente la escatología del Nuevo Testamento, en especial los dichos de Jesús sobre el Hijo del Hombre y las visiones del Apocalipsis." },
  "summary.DanLXX.significance": { fp: "wyofof", text: "Daniel afirma la soberanía de Dios sobre los imperios del mundo y su vindicación de los fieles que resisten la idolatría hasta la muerte, y da expresión clásica a la esperanza en la resurrección y al reino de Dios venidero." },
  "summary.Deut.authorship": { fp: "1bx8vxz", text: "Tradicionalmente Moisés; los especialistas lo vinculan ampliamente con la reforma del siglo VII a. C." },
  "summary.Deut.contents": { fp: "56r6i5", text: "Los discursos de despedida de Moisés, que reformulan la ley y el pacto en los llanos de Moab, y terminan con su muerte." },
  "summary.Deut.context": { fp: "1qr7vvh", text: "Uno de los libros más influyentes de la Torá griega, citado con frecuencia en el Nuevo Testamento." },
  "summary.Deut.nt": { fp: "dq3nfi", text: "El Shemá y los mandatos del Deuteronomio los citan Jesús (el mandamiento más grande; la tentación) y Pablo más que casi cualquier otro libro." },
  "summary.Deut.significance": { fp: "1ovwv6u", text: "El Deuteronomio pone en el centro el amor del pacto: «Escucha, Israel… amarás al SEÑOR tu Dios con todo tu corazón», y ata la obediencia al amor agradecido." },
  "summary.Eccl.authorship": { fp: "d41ve6", text: "Se atribuye a «Qohélet», hijo de David; su fecha se discute." },
  "summary.Eccl.contents": { fp: "b5k1iu", text: "Una reflexión escrutadora sobre lo fugaz y «vaporoso» de la vida, y el llamado a temer a Dios y a disfrutar de sus dones." },
  "summary.Eccl.context": { fp: "163h0nu", text: "Un libro sapiencial que reflexiona sobre los límites del afán humano «debajo del sol»." },
  "summary.Eccl.nt": { fp: "1amofaq", text: "Su realismo sobrio sobre la mortalidad y la vanidad subyace a los llamados neotestamentarios a poner la esperanza más allá de esta era pasajera (cf. Romanos 8:20)." },
  "summary.Eccl.significance": { fp: "1nb9wsr", text: "Deja al descubierto la vanidad del sentido fabricado por uno mismo y señala la reverencia hacia Dios como el único terreno firme." },
  "summary.EpJer.authorship": { fp: "1j1205y", text: "Obra anónima presentada como una carta de Jeremías a los desterrados, compuesta en realidad más tarde (quizá entre los siglos IV y II a. C.) y a veces anexada como capítulo sexto de Baruc." },
  "summary.EpJer.contents": { fp: "1k84are", text: "Una sátira sostenida contra la idolatría, que argumenta una y otra vez —con un estribillo recurrente— que los dioses de Babilonia son imágenes impotentes, hechas por manos humanas, que no pueden ver, hablar, moverse ni salvar, y advierte a los desterrados que no los teman ni los adoren." },
  "summary.EpJer.context": { fp: "1ilk5es", text: "Escrita para judíos que vivían en medio del culto a los ídolos del Cercano Oriente antiguo y del mundo helenístico, busca fortalecerlos frente al atractivo y a la intimidación del culto pagano." },
  "summary.EpJer.nt": { fp: "1y0n73u", text: "Su burla de los ídolos sin vida corre en paralelo con los argumentos de Pablo sobre los ídolos y el único Dios (1 Corintios 8–10) y con la polémica antiidolátrica de Hechos y de Apocalipsis." },
  "summary.EpJer.significance": { fp: "kjdn3n", text: "La carta insiste en la polémica clásica, profética y deuteronomista, de que solo el Dios vivo actúa, mientras que los ídolos no son nada. Refuerza el monoteísmo exclusivo como marca de identidad judía en un entorno pagano." },
  "summary.EsthGr.authorship": { fp: "4apip9", text: "La versión griega de Ester amplía el libro hebreo con seis «Adiciones» sustanciales de autoría desconocida. Un colofón atribuye la traducción a un tal Lisímaco de Jerusalén, y las Adiciones se compusieron probablemente en los siglos II–I a. C." },
  "summary.EsthGr.contents": { fp: "30qssq", text: "Vuelve a contar la liberación de los judíos de Persia por medio de la reina Ester y de Mardoqueo, pero añade el sueño de Mardoqueo y su interpretación, las oraciones de Mardoqueo y de Ester, el texto de los edictos reales y un marco religioso explícito, sobre todo el nombre de Dios, que en el hebreo no aparece nunca." },
  "summary.EsthGr.context": { fp: "rx8lwf", text: "Producida en el judaísmo de la diáspora y de Palestina en época helenística, la Ester griega refleja una comunidad que atesoraba el relato de Purim pero sentía que el llamativo silencio de la versión hebrea sobre Dios y la oración necesitaba remedio." },
  "summary.EsthGr.nt": { fp: "om0dyi", text: "Los temas de Ester —la providencia escondida y la caída de los poderosos— anticipan motivos de los Evangelios y de Hechos, y el patrón de liberación frente a una amenaza genocida nutre la reflexión judía y cristiana sobre la persecución y el rescate." },
  "summary.EsthGr.significance": { fp: "ry3h3v", text: "Las Adiciones vuelven manifiesta la providencia divina: lo que en hebreo se lee como coincidencia se convierte, en griego, en oración respondida y en sueño cumplido. El libro afirma que Dios preserva a su pueblo aun en el destierro y aun cuando su mano está oculta." },
  "summary.Exod.authorship": { fp: "1mzr0vy", text: "Tradicionalmente Moisés; la traducción griega pertenece al estrato más antiguo de la Septuaginta." },
  "summary.Exod.contents": { fp: "1lknvoj", text: "La esclavitud de Israel en Egipto, el éxodo bajo Moisés, el pacto y la ley en el Sinaí, y la construcción del tabernáculo." },
  "summary.Exod.context": { fp: "vp449u", text: "Parte de la Torá griega que se leía en las sinagogas de la diáspora y que se cita a lo largo del Nuevo Testamento." },
  "summary.Exod.nt": { fp: "182ssbn", text: "El éxodo, la Pascua y el pacto del Sinaí son los grandes tipos que están detrás del relato neotestamentario de la redención, de la Cena del Señor y del nuevo pacto." },
  "summary.Exod.significance": { fp: "1r6ws2c", text: "El Éxodo revela a Dios como el redentor que libra a su pueblo, le da su ley y habita en medio de él." },
  "summary.Ezek.authorship": { fp: "xbqu2y", text: "El sacerdote y profeta Ezequiel, desterrado en Babilonia." },
  "summary.Ezek.contents": { fp: "lynz3p", text: "Visiones de la gloria de Dios, juicio sobre Jerusalén y las naciones, y la promesa de un corazón y un espíritu nuevos, de huesos secos resucitados y de un templo restaurado." },
  "summary.Ezek.context": { fp: "1yjet8y", text: "Profetiza entre los desterrados babilónicos después del 597 a. C." },
  "summary.Ezek.nt": { fp: "xy6zyu", text: "Su corazón y Espíritu nuevos, la resurrección de los huesos y la imagen del río que sale del templo nutren Juan 3, la efusión del Espíritu y Apocalipsis 21–22." },
  "summary.Ezek.significance": { fp: "pu0gnp", text: "Ezequiel proclama la santidad y la soberanía de Dios y promete la renovación interior por el Espíritu de Dios y el regreso de su gloria." },
  "summary.Ezra.authorship": { fp: "1oshynh", text: "Asociado a Esdras; parte de la historia de Esdras-Nehemías." },
  "summary.Ezra.contents": { fp: "e619aw", text: "El regreso de Babilonia, la reconstrucción del templo y la reforma de Esdras, fundada en la Ley." },
  "summary.Ezra.context": { fp: "h2dtfq", text: "Ambientado en el período persa, entre los desterrados que regresan y reconstruyen su comunidad." },
  "summary.Ezra.nt": { fp: "1wysjmq", text: "La restauración posexílica que describe forma parte de la historia que el Nuevo Testamento lee como culminante en la venida de Cristo." },
  "summary.Ezra.significance": { fp: "nqlba3", text: "Celebra la fidelidad de Dios al restaurar a su pueblo y el lugar central de la Escritura en la formación de la comunidad." },
  "summary.Gen.authorship": { fp: "u7sklz", text: "Se atribuye tradicionalmente a Moisés; la investigación moderna ve el Pentateuco como un tejido de fuentes anteriores editado a lo largo de siglos. Esta es la traducción griega (Septuaginta) del siglo III a. C." },
  "summary.Gen.contents": { fp: "1todkwt", text: "El libro de los comienzos: la creación, la caída, el diluvio y Babel, y después la historia familiar de los patriarcas Abraham, Isaac, Jacob y José, hasta el descenso de Israel a Egipto." },
  "summary.Gen.context": { fp: "116frw7", text: "El Pentateuco griego se produjo para los judíos de habla griega del Egipto ptolemaico y llegó a ser la Biblia de la diáspora y, más tarde, de la iglesia primitiva." },
  "summary.Gen.nt": { fp: "pfuygc", text: "El Nuevo Testamento recurre constantemente al Génesis: la creación, Adán, la fe de Abraham y la promesa de bendición para las naciones, cumplida en Cristo." },
  "summary.Gen.significance": { fp: "3wbtof", text: "El Génesis funda toda la Escritura en el único Dios Creador, que elige un pueblo y se vincula a él por pacto y promesa." },
  "summary.Hab.authorship": { fp: "1vyhy2c", text: "El profeta Habacuc." },
  "summary.Hab.contents": { fp: "15y5oqf", text: "Un diálogo con Dios sobre el problema del mal, respondido con el llamado a que «el justo por su fe vivirá», y que termina en un himno de confianza." },
  "summary.Hab.context": { fp: "1kpppji", text: "Forcejea con el ascenso de Babilonia y con el problema de que Dios se sirva de los malvados para juzgar." },
  "summary.Hab.nt": { fp: "iu8bdz", text: "«El justo por su fe vivirá» (Habacuc 2:4) es piedra angular del evangelio de Pablo en Romanos y Gálatas, y de Hebreos 10." },
  "summary.Hab.significance": { fp: "d383fh", text: "Enseña una fe que se aferra a la justicia de Dios aun cuando sus caminos desconciertan." },
  "summary.Hag.authorship": { fp: "rgg7bw", text: "El profeta posexílico Hageo." },
  "summary.Hag.contents": { fp: "1iplepw", text: "Oráculos breves que urgen a la comunidad repatriada a reconstruir el templo, con promesas de su gloria futura." },
  "summary.Hag.context": { fp: "1tsv769", text: "Dirigido a los desterrados que habían regresado y habían descuidado la reconstrucción del templo (c. 520 a. C.)." },
  "summary.Hag.nt": { fp: "1c30olv", text: "Su promesa de que Dios «hará temblar a las naciones» y llenará su casa de gloria se retoma en Hebreos 12." },
  "summary.Hag.significance": { fp: "xoid91", text: "Llama a dar prioridad a la casa y a la honra de Dios, y promete que la gloria venidera superará a la anterior." },
  "summary.Hos.authorship": { fp: "1neo9j", text: "El profeta Oseas, del siglo VIII." },
  "summary.Hos.contents": { fp: "1j49930", text: "La infidelidad de Israel retratada a través del matrimonio atribulado de Oseas, con un juicio templado por el amor implacable de Dios." },
  "summary.Hos.context": { fp: "tjjd22", text: "Profetiza en el reino del norte, Israel, antes de su caída ante Asiria." },
  "summary.Hos.nt": { fp: "8s1l8x", text: "El Nuevo Testamento cita a Oseas para el llamado de su «hijo» desde Egipto y para su misericordia hacia un pueblo que antes era «no mi pueblo» (Mateo 2; Romanos 9; 1 Pedro 2)." },
  "summary.Hos.significance": { fp: "sc3zbc", text: "Revela el amor de pacto de Dios como el de un cónyuge herido pero fiel, que al final no soltará a su pueblo." },
  "summary.Isa.authorship": { fp: "pnuugn", text: "Se atribuye al profeta Isaías, del siglo VIII; muchos especialistas distinguen dentro de él material posterior (caps. 40–66)." },
  "summary.Isa.contents": { fp: "1iegw9", text: "Oráculos de juicio y de esperanza para Judá, la promesa de un rey venidero y de un siervo sufriente, y visiones de restauración y de nueva creación." },
  "summary.Isa.context": { fp: "1w3q6ae", text: "Abarca la amenaza asiria, el destierro babilónico y la esperanza del regreso; Isaías está entre los libros más citados en el Nuevo Testamento." },
  "summary.Isa.nt": { fp: "j5inje", text: "El Nuevo Testamento lee los cánticos del siervo de Isaías, la señal de la «virgen» y la esperanza de nueva creación como cumplidos en Jesús (Mateo; los Evangelios; Hechos 8; Romanos)." },
  "summary.Isa.significance": { fp: "56cbpk", text: "Isaías proclama al Santo de Israel que juzga y salva, y promete un redentor y una creación renovada." },
  "summary.Jdt.authorship": { fp: "qh6yt6", text: "El autor de Judit es desconocido. El libro se conserva completo solo en griego, aunque pudo tener un original hebreo." },
  "summary.Jdt.contents": { fp: "1dypyfn", text: "Cuando el general asirio Holofernes sitia su ciudad, la viuda Judit lo engaña con su belleza y su piedad, se gana su confianza y lo decapita mientras duerme, salvando así a su pueblo sin ejército alguno." },
  "summary.Jdt.context": { fp: "1l1yax5", text: "Los especialistas suelen fecharlo en el período asmoneo, hacia fines del siglo II a. C. El relato contiene errores históricos (mezcla datos asirios y persas), lo que sugiere que es una obra de ficción teológica más que de historia, escrita probablemente para alentar la resistencia judía al dominio extranjero." },
  "summary.Jdt.nt": { fp: "mnm7d5", text: "Judit pertenece al mismo género de «relato de liberación» que Ester y Daniel, donde un héroe vulnerable derrota a un enemigo poderoso mediante una astucia dada por Dios. No se lo cita directamente en el Nuevo Testamento, pero moldeó ideas judías y cristianas posteriores sobre el valor y la fidelidad. Es canónico para católicos y ortodoxos, pero no para judíos ni protestantes." },
  "summary.Jdt.significance": { fp: "jgppio", text: "Judit muestra que Israel depende solo de Dios, y no de la fuerza militar, para ser librado, y que Dios puede valerse de una persona insospechada —una viuda devota— para lograrlo. El libro subraya la observancia estricta de la ley judía como condición del favor divino." },
  "summary.Jer.authorship": { fp: "10irgx4", text: "El profeta Jeremías, con su escriba Baruc; el texto griego es notablemente más breve y de orden distinto que el hebreo." },
  "summary.Jer.contents": { fp: "12uv1l3", text: "Advertencias de la caída de Jerusalén ante Babilonia, llamados al arrepentimiento y la promesa de un nuevo pacto escrito en el corazón." },
  "summary.Jer.context": { fp: "1q2z7ow", text: "Ambientado en las últimas décadas de Judá, antes de la conquista babilónica y durante ella." },
  "summary.Jer.nt": { fp: "hx9omy", text: "El «nuevo pacto» de Jeremías 31 es central en el Nuevo Testamento: la Última Cena, 2 Corintios 3 y Hebreos 8–10." },
  "summary.Jer.significance": { fp: "1x4xd9s", text: "Jeremías sostiene a la vez el juicio por el quebrantamiento del pacto y la promesa de un pacto nuevo e interior, de perdón." },
  "summary.Job.authorship": { fp: "1g3qau0", text: "Anónimo; una obra maestra poética de fecha incierta." },
  "summary.Job.contents": { fp: "1xiw8qa", text: "El sufrimiento del justo Job, sus debates con sus amigos sobre por qué sufre, y la respuesta de Dios desde el torbellino." },
  "summary.Job.context": { fp: "1u9yf3s", text: "Un libro sapiencial que sondea la antigua pregunta por el sufrimiento del inocente." },
  "summary.Job.nt": { fp: "1jy861i", text: "Santiago señala la perseverancia de Job (Santiago 5:11), y el forcejeo del libro con el sufrimiento del inocente ilumina la teología neotestamentaria de la cruz." },
  "summary.Job.significance": { fp: "18bnhs2", text: "Job derriba la teología simple de la retribución e insiste en que los caminos de Dios exceden la comprensión humana y en que el que sufre puede seguir confiando en él." },
  "summary.Joel.authorship": { fp: "mawxwg", text: "El profeta Joel; su fecha es incierta." },
  "summary.Joel.contents": { fp: "tpxyo2", text: "Una plaga de langostas como señal del Día del Señor, con un llamado al arrepentimiento y la promesa del Espíritu de Dios derramado sobre toda carne." },
  "summary.Joel.context": { fp: "umbh3s", text: "Motivado por una devastadora plaga de langostas, leída como señal del Día del Señor." },
  "summary.Joel.nt": { fp: "e166w9", text: "Pedro proclama cumplida en Pentecostés la promesa de Joel sobre el Espíritu derramado (Hechos 2)." },
  "summary.Joel.significance": { fp: "m9po61", text: "Une el arrepentimiento urgente con la esperanza de restauración y con el don universal del Espíritu." },
  "summary.Jonah.authorship": { fp: "pf1j30", text: "Relato anónimo sobre el profeta Jonás." },
  "summary.Jonah.contents": { fp: "sw325n", text: "La huida de Jonás del llamado de Dios, el gran pez y su predicación a regañadientes en Nínive, que se arrepiente, para disgusto de Jonás." },
  "summary.Jonah.context": { fp: "1qwgcbh", text: "Un relato profético que sondea la misericordia de Dios hacia los enemigos de Israel." },
  "summary.Jonah.nt": { fp: "1redu0j", text: "Jesús convierte la «señal de Jonás» en indicio de su propia muerte y resurrección y del arrepentimiento de los gentiles (Mateo 12)." },
  "summary.Jonah.significance": { fp: "nmnpms", text: "Enseña la misericordia soberana de Dios, que alcanza incluso a una ciudad enemiga y pagana, y reprende el nacionalismo estrecho." },
  "summary.JoshB.authorship": { fp: "qphqdr", text: "Anónimo; el Josué de la Septuaginta (en la tradición del Códice Vaticano) es una forma más breve y distinta del libro." },
  "summary.JoshB.contents": { fp: "yizwhh", text: "La conquista y el reparto de la tierra prometida bajo Josué, y la renovación del pacto en Siquem («escojan hoy a quién han de servir»)." },
  "summary.JoshB.context": { fp: "19kmfl3", text: "Continúa los libros históricos griegos que se leían en el judaísmo de la diáspora." },
  "summary.JoshB.nt": { fp: "jcsijm", text: "Hebreos contrasta el reposo de Josué con el reposo mayor que queda en Cristo (Hebreos 4), y Josué (Iēsous en griego) prefigura el nombre de Jesús." },
  "summary.JoshB.significance": { fp: "1engbhv", text: "Josué retrata a Dios como el dador fiel de la herencia prometida, que llama a su pueblo a una lealtad de todo corazón." },
  "summary.JudgB.authorship": { fp: "1f4tbh0", text: "Anónimo; una compilación de tradiciones antiguas en vestidura griega." },
  "summary.JudgB.contents": { fp: "1effort", text: "La época turbulenta de los «jueces»: apostasía cíclica, opresión y liberación por medio de figuras como Débora, Gedeón y Sansón." },
  "summary.JudgB.context": { fp: "1xc1nyj", text: "Parte del corpus histórico griego del judaísmo del Segundo Templo." },
  "summary.JudgB.nt": { fp: "giyuod", text: "Hebreos 11 enumera a varios jueces entre los héroes de la fe, y el patrón de libertadores levantados por Dios enmarca la esperanza neotestamentaria de un Salvador definitivo." },
  "summary.JudgB.significance": { fp: "x8kpsi", text: "Jueces ilustra la ruina que sigue a la infidelidad al pacto y la misericordia repetida de Dios al levantar libertadores." },
  "summary.Lam.authorship": { fp: "hbcfke", text: "Tradicionalmente, Jeremías." },
  "summary.Lam.contents": { fp: "n8szb0", text: "Cinco poemas que lloran la destrucción de Jerusalén y terminan con una súplica de restauración, entre afirmaciones de la misericordia de Dios." },
  "summary.Lam.context": { fp: "1xp24g9", text: "Una respuesta a la destrucción de Jerusalén por Babilonia en el 587 a. C." },
  "summary.Lam.nt": { fp: "3nxzvq", text: "Su lamento por la ciudad caída está detrás del llanto de Jesús sobre Jerusalén (Lucas 19) y de la teología neotestamentaria del sufrimiento y la esperanza." },
  "summary.Lam.significance": { fp: "p6sakl", text: "Da voz autorizada al duelo, mientras confiesa que «nuevas son cada mañana sus misericordias» aun en la catástrofe." },
  "summary.Lev.authorship": { fp: "tef1j8", text: "Tradicionalmente Moisés; parte de la legislación sacerdotal del Pentateuco." },
  "summary.Lev.contents": { fp: "gyydj8", text: "Leyes de sacrificio, sacerdocio, pureza y santidad, incluidos el Día de la Expiación y el Código de Santidad («sean santos, porque yo soy santo»)." },
  "summary.Lev.context": { fp: "cp7j2x", text: "Parte de la Torá griega; su vocabulario sacrificial moldeó el lenguaje cultual de la Septuaginta." },
  "summary.Lev.nt": { fp: "1t8ynxm", text: "Su sistema sacrificial y sacerdotal aporta la clave interpretativa para la presentación que hace Hebreos del sacrificio de Cristo, hecho una vez por todas, y para el lenguaje neotestamentario de la santidad." },
  "summary.Lev.significance": { fp: "1xlp4f9", text: "El Levítico expone cómo un Dios santo puede habitar con su pueblo por medio de la expiación y de la santidad." },
  "summary.Mal.authorship": { fp: "6nlz6d", text: "El profeta posexílico Malaquías (o «mi mensajero»)." },
  "summary.Mal.contents": { fp: "967l89", text: "Disputas que reprenden el culto descuidado y la infidelidad, y prometen un mensajero venidero y el Día del SEÑOR." },
  "summary.Mal.context": { fp: "1qg127y", text: "Aborda la tibieza espiritual de la comunidad restaurada, probablemente en el siglo V a. C." },
  "summary.Mal.nt": { fp: "1sauygw", text: "El mensajero prometido de Malaquías y su «Elías» se identifican con Juan el Bautista, que prepara el camino de Cristo (Mateo 11; Marcos 1)." },
  "summary.Mal.significance": { fp: "6bud20", text: "Llama a la fidelidad al pacto y promete la venida del SEÑOR, precedida por su mensajero." },
  "summary.Mic.authorship": { fp: "12oyztt", text: "El profeta Miqueas, del siglo VIII." },
  "summary.Mic.contents": { fp: "1wdin17", text: "Juicio sobre Samaria y Jerusalén junto con la esperanza de un gobernante que saldrá de Belén, y el célebre llamado a «hacer justicia, amar misericordia y caminar humildemente con tu Dios»." },
  "summary.Mic.context": { fp: "1bgm2gt", text: "Contemporáneo de Isaías, profetiza contra la injusticia en Judá." },
  "summary.Mic.nt": { fp: "4gwhfp", text: "La profecía de Belén de Miqueas se aplica al nacimiento de Jesús (Mateo 2), y su resumen ético resuena por toda la enseñanza neotestamentaria." },
  "summary.Mic.significance": { fp: "1e8bru5", text: "Enlaza la justicia social, la esperanza del pacto y la promesa de un gobernante pastor que ha de venir." },
  "summary.Nah.authorship": { fp: "wq5h0j", text: "El profeta Nahúm." },
  "summary.Nah.contents": { fp: "123ptj0", text: "Una proclamación poética de la caída de Nínive, capital del opresivo imperio asirio." },
  "summary.Nah.context": { fp: "1ydleqp", text: "Un oráculo que celebra la caída inminente de Nínive, capital de Asiria." },
  "summary.Nah.nt": { fp: "1lyx0cs", text: "Su confianza en que Dios derriba al imperio arrogante resuena con el juicio de «Babilonia» en el Apocalipsis." },
  "summary.Nah.significance": { fp: "1q30g0f", text: "Afirma que Dios es un juez justo que derriba a los poderes tiránicos, y consuela a los oprimidos." },
  "summary.Neh.authorship": { fp: "zin0yp", text: "Se apoya en las memorias del propio Nehemías." },
  "summary.Neh.contents": { fp: "zwhqgz", text: "La reconstrucción de las murallas de Jerusalén y la renovación del pacto bajo Nehemías y Esdras, con la lectura pública de la Ley." },
  "summary.Neh.context": { fp: "ipkzmo", text: "Ambientado en el período persa, en la reconstrucción de Jerusalén." },
  "summary.Neh.nt": { fp: "1mqic3k", text: "Su lectura y exposición públicas de la Escritura anticipan el marco sinagogal del Nuevo Testamento y el ministerio de la palabra en la iglesia." },
  "summary.Neh.significance": { fp: "16xipmj", text: "Ofrece un modelo de liderazgo, oración y renovación del pacto centrado en oír y obedecer la Escritura." },
  "summary.Num.authorship": { fp: "o8hbrd", text: "Tradicionalmente Moisés; parte del Pentateuco." },
  "summary.Num.contents": { fp: "1pe3c6g", text: "Las peregrinaciones de Israel por el desierto, del Sinaí hacia Canaán, con censos, rebeliones y legislación adicional." },
  "summary.Num.context": { fp: "1u38r7n", text: "Parte de la Torá griega del judaísmo de la diáspora." },
  "summary.Num.nt": { fp: "kshlr6", text: "Pablo lee a la generación del desierto como advertencia para la iglesia (1 Corintios 10), y episodios como el de la serpiente de bronce se aplican a Cristo (Juan 3)." },
  "summary.Num.significance": { fp: "1dpmgfw", text: "Números muestra la fidelidad y el juicio de Dios mientras conduce por el desierto, hacia la promesa, a un pueblo que murmura." },
  "summary.Obad.authorship": { fp: "1h7ozlb", text: "El profeta Abdías; el libro más breve del Antiguo Testamento." },
  "summary.Obad.contents": { fp: "sbptoc", text: "Un oráculo de juicio contra Edom por su violencia y su regodeo, y la promesa del reino del SEÑOR." },
  "summary.Obad.context": { fp: "1c7yi4f", text: "Un solo oráculo motivado por la hostilidad de Edom hacia Judá en el momento de la caída de Jerusalén." },
  "summary.Obad.nt": { fp: "1eu0c0w", text: "Su confianza en el reino venidero de Dios resuena con la proclamación central del Nuevo Testamento sobre el reinado de Dios." },
  "summary.Obad.significance": { fp: "10t82q", text: "Afirma que Dios juzga la crueldad de las naciones y que «el reino será del SEÑOR»." },
  "summary.Odes.authorship": { fp: "acgdqv", text: "Un apéndice litúrgico del Salterio en algunos manuscritos de la Septuaginta (sobre todo el Códice Alejandrino), que reúne cánticos de diversa autoría bíblica y cristiana primitiva para el culto." },
  "summary.Odes.contents": { fp: "xotxje", text: "Una colección de cánticos bíblicos —como los cánticos de Moisés (Éxodo 15; Deuteronomio 32), de Ana, de Habacuc y de los tres jóvenes— junto con cánticos del Nuevo Testamento como el Magníficat, el Benedictus y el Nunc dimittis, y un himno matutino cristiano antiguo." },
  "summary.Odes.context": { fp: "h109ho", text: "Refleja la práctica de la iglesia primitiva de habla griega, que reunió los cánticos de la Escritura junto a los Salmos como himnario para la oración diaria." },
  "summary.Odes.nt": { fp: "o5rerb", text: "Como incluye los cánticos lucanos y un himno antiguo, la colección conserva y enmarca directamente material de culto neotestamentario y atestigua cómo oraba las Escrituras la iglesia primitiva." },
  "summary.Odes.significance": { fp: "1w41f42", text: "Las Odas muestran el culto como el repaso de los actos salvadores de Dios, y enlazan los cánticos de la liberación de Israel con la alabanza de la iglesia por la redención en Cristo." },
  "summary.Prov.authorship": { fp: "12qvze5", text: "Asociado a Salomón y a otros sabios nombrados." },
  "summary.Prov.contents": { fp: "10nlmyo", text: "Colecciones de proverbios e instrucción sapiencial sobre la vida sabia y recta, enmarcadas por la figura personificada de la Sabiduría." },
  "summary.Prov.context": { fp: "h535rp", text: "Parte de la tradición sapiencial de Israel, moldeada para la formación moral de los jóvenes." },
  "summary.Prov.nt": { fp: "1bqlna9", text: "La Sabiduría personificada (Proverbios 8) nutre la cristología sapiencial del Nuevo Testamento, y la ética del libro resuena por todo Santiago y las epístolas." },
  "summary.Prov.significance": { fp: "17ylowi", text: "Enseña que «el temor del SEÑOR es el principio de la sabiduría», y ata la destreza práctica para vivir a la reverencia hacia Dios." },
  "summary.Ps.authorship": { fp: "1egorw7", text: "Una colección de 150 salmos de muchos autores, muchos de ellos vinculados a David; el Salterio griego incluye un Salmo 151 adicional." },
  "summary.Ps.contents": { fp: "tjl1zv", text: "El himnario de Israel: alabanza, lamento, acción de gracias y confianza, reunidos para el culto." },
  "summary.Ps.context": { fp: "su98y3", text: "El libro de oración de Israel, usado en el templo y en la sinagoga, y el libro del Antiguo Testamento más citado en el Nuevo." },
  "summary.Ps.nt": { fp: "1jt2ae9", text: "El Nuevo Testamento cita los Salmos sin cesar: para la filiación, el sufrimiento, la resurrección y el reinado de Cristo (p. ej., Salmos 2, 22, 110, 118)." },
  "summary.Ps.significance": { fp: "1jwby26", text: "Los Salmos dan voz a toda la gama de la fe delante de Dios y guardan ricas esperanzas mesiánicas y del reino." },
  "summary.PsSol.authorship": { fp: "123my79", text: "Un autor o grupo desconocido, probablemente ligado a la piedad farisea temprana, escribió estos dieciocho salmos en hebreo (hoy perdido; se conservan en griego), atribuidos falsamente a Salomón." },
  "summary.PsSol.contents": { fp: "q2r96f", text: "Los salmos critican a los sacerdotes-reyes asmoneos por corromper el Templo y usurpar el trono que correspondía por derecho al linaje de David, e interpretan la conquista romana como juicio de Dios sobre esa corrupción." },
  "summary.PsSol.context": { fp: "ogc8oo", text: "Como varios salmos describen con claridad la conquista de Jerusalén por el general romano Pompeyo en el 63 a. C. y su muerte en el 48 a. C., esta colección puede fecharse con una seguridad poco común a mediados del siglo I a. C." },
  "summary.PsSol.nt": { fp: "sd58cg", text: "Esta viva esperanza mesiánica regia constituye un trasfondo imprescindible para entender las expectativas políticas y religiosas de las que los primeros cristianos se sirvieron, y que reinterpretaron, al proclamar a Jesús como Mesías. No tiene condición canónica en el judaísmo ni en el cristianismo mayoritarios." },
  "summary.PsSol.significance": { fp: "mzgk9g", text: "El salmo 17 ofrece uno de los cuadros más claros de toda la literatura judía sobre la esperanza en un «hijo de David» justo y venidero que purgará Jerusalén de sus opresores y reinará en santidad." },
  "summary.Ruth.authorship": { fp: "1iocgps", text: "Anónimo." },
  "summary.Ruth.contents": { fp: "f91xk9", text: "La historia de Rut la moabita, cuya lealtad a Noemí y cuyo matrimonio con Booz la colocan en la ascendencia del rey David." },
  "summary.Ruth.context": { fp: "1wgunuu", text: "Un relato breve ambientado en la época de los jueces, apreciado tanto en la tradición judía como en la cristiana." },
  "summary.Ruth.nt": { fp: "17pu4q8", text: "Rut aparece en la genealogía de Jesús en Mateo, y su inclusión señala el alcance del evangelio hacia las naciones." },
  "summary.Ruth.significance": { fp: "1pf8bh6", text: "Rut muestra la providencia callada de Dios y la lealtad del pacto (jésed), y su acogida de una extranjera dentro de su pueblo." },
  "summary.Sir.authorship": { fp: "g9ujr5", text: "Escrito en hebreo por Jesús ben Sirá, escriba y maestro de Jerusalén, hacia el año 180 a. C., y traducido al griego por su nieto, que aporta un prólogo fechado, después del 132 a. C." },
  "summary.Sir.contents": { fp: "m8n9lq", text: "Una larga colección de enseñanza sapiencial sobre la conducta diaria, la amistad, la palabra, la riqueza, la humildad, las mujeres y, sobre todo, el temor del Señor, que cierra con un «Elogio de los padres» donde se celebra a las grandes figuras de Israel, desde los patriarcas hasta el sumo sacerdote Simón." },
  "summary.Sir.context": { fp: "pkszxu", text: "Compuesto justo antes de la crisis macabea, refleja a un sabio jerosolimitano culto que recomienda a los jóvenes la piedad y la sabiduría tradicionales en medio de las presiones de la cultura helenística." },
  "summary.Sir.nt": { fp: "1k29ys8", text: "Su Sabiduría personificada que «planta su tienda» en Israel está detrás del Logos de Juan y de la cristología sapiencial, y su enseñanza ética sobre la palabra, la riqueza y el perdón corre muy en paralelo con Santiago y con el Sermón del Monte." },
  "summary.Sir.significance": { fp: "11tpfrv", text: "Ben Sirá funde la sabiduría con la Torá: la verdadera sabiduría se halla en el temor del Señor y en guardar los mandamientos. Su identificación de la Sabiduría con la Ley (cap. 24) moldeó la reflexión judía y cristiana posterior sobre la Sabiduría divina." },
  "summary.Song.authorship": { fp: "ixo6ud", text: "Se atribuye a Salomón." },
  "summary.Song.contents": { fp: "1bkau1e", text: "Un ciclo de poesía amorosa entre una esposa y un esposo que celebra la bondad del amor del pacto." },
  "summary.Song.context": { fp: "1p6p1ul", text: "Poesía amorosa conservada en las Escrituras de Israel y leída alegóricamente en la tradición judía y en la cristiana." },
  "summary.Song.nt": { fp: "u8qlbw", text: "Las imágenes de esposa y esposo nutren el retrato neotestamentario de Cristo y la iglesia (Efesios 5; Apocalipsis 19–21)." },
  "summary.Song.significance": { fp: "gsq55w", text: "Más allá de su celebración del amor humano, se leyó como imagen del amor entre Dios y su pueblo." },
  "summary.Sus.authorship": { fp: "6m905o", text: "Susana es un relato breve anónimo agregado al libro de Daniel, escrito probablemente en su origen en una lengua semítica, aunque no se conserva ningún original." },
  "summary.Sus.contents": { fp: "75bhiz", text: "Dos ancianos malvados acusan falsamente de adulterio a la virtuosa Susana después de que ella rechaza sus insinuaciones. El joven Daniel demuestra su inocencia interrogando con astucia a los ancianos por separado, con lo que quedan al descubierto sus relatos contradictorios." },
  "summary.Sus.context": { fp: "eyvqsg", text: "Escrito probablemente en el siglo II a. C., refleja preocupaciones judías por los juicios justos, por la exigencia bíblica de varios testigos y por el temor a los jueces corruptos." },
  "summary.Sus.nt": { fp: "1i6r37v", text: "Como otros relatos de «el joven sabio que desenmascara a los ancianos corruptos», Susana resuena con las preocupaciones neotestamentarias por el falso testimonio y el juicio injusto (como en el propio proceso de Jesús). Forma parte del Daniel católico y ortodoxo, y queda excluida de las Biblias hebrea y protestante." },
  "summary.Sus.significance": { fp: "1r7odqs", text: "El relato muestra que Dios vindica al inocente aun cuando los tribunales humanos fallan, y que lo hace por medio de la sabiduría que el Espíritu da a un joven; además presenta la castidad y la integridad como ideales que vale la pena defender bajo presión." },
  "summary.Tob.authorship": { fp: "qs8tg0", text: "Tobías es una obra de ficción anónima, escrita en arameo o en hebreo (en Qumrán se hallaron fragmentos de ambas lenguas). El relato se cuenta en la voz de Tobit y de su hijo Tobías, pero nadie cree que ellos lo escribieran de verdad." },
  "summary.Tob.contents": { fp: "70fj49", text: "Tobit, un hombre ciego y justo, envía a su hijo Tobías a un viaje guiado —sin que él lo sepa— por el ángel Rafael disfrazado. Tobías se casa con Sara, cuyos siete maridos anteriores murieron a manos de un demonio, y cura la ceguera de su padre con la hiel de un pez, siguiendo las instrucciones de Rafael." },
  "summary.Tob.context": { fp: "110p12w", text: "Probablemente se escribió en la diáspora oriental o en Palestina, a fines del siglo III o comienzos del II a. C., antes de la rebelión macabea. Refleja las preocupaciones cotidianas de los judíos que vivían bajo dominio extranjero: guardar la ley, casarse dentro de la comunidad, dar a los pobres y enterrar a los muertos como corresponde." },
  "summary.Tob.nt": { fp: "1iq40n1", text: "Los temas de Tobías —la providencia divina que obra por medio de agentes ocultos— y su elogio de la generosidad hacen eco de la enseñanza ética posterior del Nuevo Testamento, aunque allí no se lo cita directamente. Fue aceptado como Escritura por católicos y ortodoxos, pero quedó excluido del canon hebreo y del protestante." },
  "summary.Tob.significance": { fp: "xv6ypf", text: "El libro enseña que Dios cuida de la gente común y fiel por medios callados y cotidianos, y no mediante milagros espectaculares. La limosna, la oración y la lealtad a la familia y a la ley se presentan como el camino que Dios recompensa. El relato muestra además un interés temprano en los ángeles y los demonios." },
  "summary.Wis.authorship": { fp: "170zjj7", text: "Aunque se presenta como palabras de Salomón, el libro lo escribió en realidad mucho después un autor judío desconocido y de gran cultura, en Alejandría, que nunca menciona el nombre de Salomón de manera directa." },
  "summary.Wis.contents": { fp: "f9bx6n", text: "El libro tiene tres partes: la suerte de los justos frente a la de los impíos, el elogio de la Sabiduría personificada, y un repaso de la historia de Israel (especialmente el éxodo) que muestra la mano rectora de la Sabiduría, junto con la burla del culto egipcio a los ídolos." },
  "summary.Wis.context": { fp: "ntiii2", text: "La mayoría de los especialistas lo fecha entre fines del siglo II a. C. y comienzos del I d. C., posiblemente como respuesta a la persecución de los judíos bajo el dominio romano en Egipto. Su autor conocía bien la filosofía griega, sobre todo el platonismo y el estoicismo." },
  "summary.Wis.nt": { fp: "cku2yt", text: "El retrato que hace Sabiduría de Salomón de la Sabiduría como agente de Dios en la creación influyó hondamente en el modo en que los autores del Nuevo Testamento, sobre todo Pablo y Juan, describieron el papel de Cristo en la creación. Nunca formó parte de la Biblia hebrea y queda excluido de la Escritura protestante, aunque católicos y ortodoxos lo aceptan." },
  "summary.Wis.significance": { fp: "hqrlz4", text: "Su mayor aporte es describir a la Sabiduría casi como un ser divino aparte, que se difunde por la creación y la ordena. El libro enseña además con claridad la inmortalidad del alma, apartándose de la esperanza en la resurrección corporal que se halla en otros escritos judíos del período." },
  "summary.Zech.authorship": { fp: "1prnbjo", text: "El profeta posexílico Zacarías." },
  "summary.Zech.contents": { fp: "sxg0kn", text: "Visiones nocturnas y oráculos que alientan la reconstrucción del templo y miran hacia un rey humilde venidero, un traspasado y el reinado universal del SEÑOR." },
  "summary.Zech.context": { fp: "19w916k", text: "Contemporáneo de Hageo, alienta la reconstrucción del templo (c. 520–518 a. C.)." },
  "summary.Zech.nt": { fp: "1nrxcdd", text: "Los Evangelios aplican Zacarías a Jesús: el rey sobre un asno, las treinta piezas de plata, el traspasado y el pastor herido." },
  "summary.Zech.significance": { fp: "1my80u5", text: "Funde el aliento presente con una viva esperanza mesiánica y escatológica." },
  "summary.Zeph.authorship": { fp: "1iotfko", text: "El profeta Sofonías." },
  "summary.Zeph.contents": { fp: "gaznrm", text: "Advertencias del Día del SEÑOR contra Judá y las naciones, que terminan con una promesa de gozo para un remanente humilde." },
  "summary.Zeph.context": { fp: "bcc3ru", text: "Profetiza en Judá, probablemente antes de la reforma de Josías." },
  "summary.Zeph.nt": { fp: "y6fs4t", text: "Sus temas del Día del SEÑOR y del remanente fiel alimentan directamente la escatología neotestamentaria y la esperanza de los pobres en espíritu." },
  "summary.Zeph.significance": { fp: "1lrg40j", text: "Proclama un juicio universal y la salvación de un remanente humilde que busca a Dios." },
  "summary.against-apion.authorship": { fp: "xp102i", text: "Josefo escribió él mismo esta defensa del judaísmo en dos libros, probablemente poco después de terminar las Antigüedades, a mediados o fines de la década del 90 d. C." },
  "summary.against-apion.contents": { fp: "j461jn", text: "Josefo refuta de forma sistemática acusaciones concretas contra los judíos y, al hacerlo, conserva citas valiosas de historiadores antiguos hoy perdidos." },
  "summary.against-apion.context": { fp: "mf1pgy", text: "La obra responde a las calumnias antijudías que circulaban en el Egipto helenístico, sobre todo las difundidas por el escritor alejandrino Apión, y defiende la antigüedad y la respetabilidad moral de los judíos ante un público gentil culto." },
  "summary.against-apion.nt": { fp: "sbza1j", text: "Su descripción de un canon bíblico ya asentado ofrece una comparación útil para entender cómo se formó la colección bíblica de los propios autores del Nuevo Testamento. La obra no tiene condición canónica, pero es históricamente importante para el estudio de la polémica antijudía antigua y de la formación del canon." },
  "summary.against-apion.significance": { fp: "1b6gs7l", text: "La obra contiene una de las declaraciones antiguas más claras de un canon bíblico judío fijo: Josefo enumera veintidós libros sagrados que considera inspirados de manera única y coherentes entre sí." },
  "summary.antiquities.authorship": { fp: "1yoytdo", text: "Escrita en griego por el historiador judío Flavio Josefo (José ben Matías), sacerdote y antiguo jefe rebelde, y terminada hacia los años 93–94 d. C. en Roma bajo el mecenazgo flavio." },
  "summary.antiquities.contents": { fp: "vmyldk", text: "Una historia del pueblo judío en veinte libros, desde la creación hasta la víspera de la rebelión contra Roma (66 d. C.), que vuelve a narrar el relato bíblico y luego lleva la historia a través del período del Segundo Templo, los asmoneos, Herodes y el dominio romano." },
  "summary.antiquities.context": { fp: "hpbd6d", text: "Josefo escribió para un público grecorromano después de la rebelión judía, buscando recomendar la antigüedad, la dignidad y la sensatez del pueblo judío y de su ley ante un auditorio imperial escéptico." },
  "summary.antiquities.nt": { fp: "lvy9yv", text: "Es una fuente primaria para el mundo del Nuevo Testamento: Herodes, los sumos sacerdotes, los gobernadores romanos, los partidos (fariseos, saduceos, esenios) y los célebres pasajes (discutidos) que mencionan a Juan el Bautista, a Santiago y a Jesús." },
  "summary.antiquities.significance": { fp: "1bhnvxp", text: "Josefo presenta la historia de Israel como prueba de que Dios recompensa la obediencia a la ley y castiga su descuido, y defiende el monoteísmo y la ética judíos como antiguos y filosóficamente respetables." },
  "summary.apocmoses.authorship": { fp: "1jp2mx5", text: "La forma griega de la Vida de Adán y Eva, obra judía anónima (con transmisión cristiana posterior) de los primeros siglos de nuestra era." },
  "summary.apocmoses.contents": { fp: "1cpu3xh", text: "La historia de Adán y Eva después del Edén: su penitencia, la muerte y sepultura de Adán, el relato que Eva hace de la caída, y las esperanzas de resurrección futura." },
  "summary.apocmoses.context": { fp: "xl4aie", text: "Amplía el relato del Génesis sobre la primera pareja y refleja la especulación judía (y después cristiana) sobre la caída y sus consecuencias." },
  "summary.apocmoses.nt": { fp: "1hcazh6", text: "Su reflexión sobre el pecado de Adán que trae la muerte y sobre la esperanza de la resurrección corre en paralelo con la teología paulina de Adán y Cristo (Romanos 5; 1 Corintios 15)." },
  "summary.apocmoses.significance": { fp: "1x8nffr", text: "Explora el origen de la muerte por el pecado y la esperanza de la resurrección corporal y de la restauración." },
  "summary.aristeas.authorship": { fp: "p2jgxm", text: "Un autor judío alejandrino desconocido escribió este texto fingiendo ser un cortesano griego llamado Aristeas, y describió sucesos que en realidad no pudo haber presenciado." },
  "summary.aristeas.contents": { fp: "1manayj", text: "La carta cuenta cómo setenta y dos traductores judíos, trabajando por separado, produjeron de manera milagrosa traducciones griegas idénticas de la Torá (el origen del término «Septuaginta»), enmarcado todo por un largo diálogo filosófico de banquete sobre la realeza y la virtud." },
  "summary.aristeas.context": { fp: "ev4qbq", text: "Aunque dice describir sucesos ocurridos bajo Ptolomeo II (285–246 a. C.), sus errores históricos muestran que se escribió en realidad a mediados o fines del siglo II a. C., y que atendía la inquietud de los judíos de la diáspora por leer la Escritura en griego y no en hebreo." },
  "summary.aristeas.nt": { fp: "19m7e7c", text: "Esta defensa de la autoridad de la Biblia griega importa directamente para el Nuevo Testamento, ya que sus autores suelen citar el Antiguo Testamento en esa forma griega (la Septuaginta). No tiene condición canónica propia, pero moldeó el modo en que judíos y cristianos vieron la Biblia griega." },
  "summary.aristeas.significance": { fp: "5mjruz", text: "Al afirmar que hubo unanimidad milagrosa entre los traductores, la carta sostiene que la traducción griega misma lleva autoridad divina, y no solo el original hebreo." },
  "summary.ascension-of-isaiah.authorship": { fp: "j430e3", text: "Una obra compuesta que une un «Martirio de Isaías» judío con material apocalíptico cristiano, y que alcanzó su forma actual en los primeros siglos cristianos." },
  "summary.ascension-of-isaiah.contents": { fp: "nxtahf", text: "El rey Manasés parte a Isaías en dos con una sierra; después, en una visión, el profeta asciende por los siete cielos y prevé el descenso, la encarnación y la exaltación de Cristo." },
  "summary.ascension-of-isaiah.context": { fp: "gv0hz5", text: "Enlaza la leyenda judía del mártir con la tradición visionaria cristiana primitiva, y refleja la cristología en desarrollo de la iglesia." },
  "summary.ascension-of-isaiah.nt": { fp: "wj174m", text: "Su relato del descenso del Amado por los cielos y de su exaltación ofrece paralelos llamativos con los himnos cristológicos del Nuevo Testamento (Filipenses 2) y con la alusión de Hebreos 11:37 al profeta «aserrado»." },
  "summary.ascension-of-isaiah.significance": { fp: "lc45ag", text: "Retrata el descenso celestial de Cristo y su regreso en gloria, y honra al profeta mártir que lo previó." },
  "summary.assumption-moses.authorship": { fp: "fx63z7", text: "Anónimo; se lo llama también Testamento de Moisés; escrito en el siglo I d. C., y conservado solo en un único palimpsesto latino incompleto." },
  "summary.assumption-moses.contents": { fp: "1r30snj", text: "La profecía de despedida de Moisés a Josué, que recorre la historia de Israel hasta los asmoneos y Herodes, la persecución y el martirio del justo Taxo, y la aparición venidera del reino de Dios. El manuscrito se corta sin terminar." },
  "summary.assumption-moses.context": { fp: "cbvugn", text: "Compuesto en Judea hacia la muerte de Herodes o poco después, en círculos que resistían la componenda con el dominio extranjero." },
  "summary.assumption-moses.nt": { fp: "eyhm4f", text: "Suele sostenerse que su final perdido está detrás de Judas 9, donde Miguel disputa con el diablo por el cuerpo de Moisés: la única alusión clara del Nuevo Testamento a este libro." },
  "summary.assumption-moses.significance": { fp: "ptnrx", text: "Insiste en que la liberación viene solo de Dios, sin revuelta humana, y en que los justos que sufren serán vindicados." },
  "summary.heading.authorship": { fp: "17dl5ho", text: "Autoría" },
  "summary.heading.contents": { fp: "11hparn", text: "Contenido" },
  "summary.heading.context": { fp: "1fi068i", text: "Contexto histórico" },
  "summary.heading.nt": { fp: "14hbqll", text: "Relación con el Nuevo Testamento" },
  "summary.heading.significance": { fp: "5bcdg1", text: "Importancia teológica" },
  "summary.jewish-war.authorship": { fp: "lqwawj", text: "Josefo escribió él mismo esta obra, primero en arameo para las comunidades judías de oriente y después, con ayuda de colaboradores griegos, en la pulida versión griega que se conserva." },
  "summary.jewish-war.contents": { fp: "v7aqq4", text: "El libro narra el estallido de la guerra, las batallas principales, el asedio y la caída de Jerusalén y la última resistencia en Masada, a partir de la propia experiencia de Josefo como participante." },
  "summary.jewish-war.context": { fp: "webn1u", text: "Publicada por partes durante la década del 70 d. C. bajo el mecenazgo directo de los emperadores Vespasiano y Tito, la obra abarca la historia judía desde el período asmoneo hasta la rebelión contra Roma (66–73 d. C.) y la destrucción del Templo en el año 70." },
  "summary.jewish-war.nt": { fp: "187ae1", text: "La información detallada del libro sobre la geografía de Jerusalén, la arquitectura del Templo y la vida política y sectaria judía es valiosa para entender el escenario de los Evangelios y de Hechos. No tiene condición canónica, pero es evidencia histórica imprescindible." },
  "summary.jewish-war.significance": { fp: "fh8ogl", text: "Josefo interpreta la guerra y la destrucción del Templo como castigo divino por la violencia entre facciones judías y por la contaminación del santuario, lo que le permite defender la fidelidad continuada de Dios y a la vez explicar la derrota catastrófica." },
  "summary.josaseneth.authorship": { fp: "1j2379b", text: "Un autor desconocido, probablemente un judío egipcio, escribió esta novela romántica que amplía la breve nota bíblica de que José se casó con Asenet (Génesis 41:45)." },
  "summary.josaseneth.contents": { fp: "ky1ore", text: "La orgullosa Asenet desprecia al principio a José, luego se enamora de él, se arrepiente de manera dramática del culto a los ídolos y queda transformada por un ángel que le da a comer un panal simbólico; más adelante una trama del hijo del faraón amenaza a la pareja." },
  "summary.josaseneth.context": { fp: "npyi7z", text: "La mayoría de los especialistas la fecha entre el siglo I a. C. y comienzos del II d. C., escrita para atender la inquietud judía por los matrimonios mixtos entre patriarcas y mujeres gentiles." },
  "summary.josaseneth.nt": { fp: "p0k4li", text: "Sus imágenes de transformación mediante un alimento simbólico («pan de vida», «copa de inmortalidad») aportan una comparación útil para la teología cristiana primitiva del bautismo y de la comunión. No tiene condición canónica en ninguna tradición." },
  "summary.josaseneth.significance": { fp: "22o8t3", text: "La conversión de Asenet —destruir sus ídolos, ayunar en penitencia y recibir vida nueva por acción angélica— ofrece un modelo rico de cómo podía verse una conversión religiosa plena a la comunidad del pacto." },
  "summary.jubilees.authorship": { fp: "1055j8d", text: "Un autor desconocido, probablemente muy ligado a los círculos sacerdotales y escribales que después se asociaron con Qumrán, escribió Jubileos en hebreo." },
  "summary.jubilees.contents": { fp: "1roeho7", text: "Presentado como revelación dada a Moisés en el Sinaí, Jubileos vuelve a contar el Génesis y parte del Éxodo, organiza la historia en períodos de 49 años («jubileos») e insiste en un calendario solar de 364 días, frente a los calendarios lunares de los grupos rivales." },
  "summary.jubilees.context": { fp: "1bdizwj", text: "Compuesto hacia mediados del siglo II a. C., probablemente justo antes de la crisis macabea o durante ella, gozó de enorme popularidad en Qumrán, donde se hallaron al menos catorce copias." },
  "summary.jubilees.nt": { fp: "1wcgv6u", text: "Jubileos muestra el tipo de disputas estrictas sobre calendario y pureza que había en el judaísmo de la época de Jesús, un trasfondo pertinente para los debates neotestamentarios sobre la observancia de la ley. No tiene condición canónica en el judaísmo ni en el cristianismo mayoritarios, pero moldeó hondamente la teología y la práctica de la comunidad de Qumrán." },
  "summary.jubilees.significance": { fp: "1019rmu", text: "El libro desarrolla una angelología y una demonología marcadas (incluida la figura del demonio Mastema) y subraya la circuncisión, el calendario correcto y la separación de los gentiles como marcas esenciales de la pertenencia verdadera al pacto." },
  "summary.lae.authorship": { fp: "y2n4to", text: "Un autor desconocido escribió la versión original, que hoy se conserva en varias traducciones distintas, a veces muy distintas entre sí (griega, latina, armenia, georgiana y eslava)." },
  "summary.lae.contents": { fp: "7vzzpr", text: "El libro cuenta la vida de Adán y Eva después de su expulsión del Edén, incluido el relato que Eva hace de la tentación (que la culpa más de lo que lo hace el Génesis), y sus muertes y sepulturas." },
  "summary.lae.context": { fp: "1ntdul", text: "La mayoría de los especialistas propone un origen judío en torno al siglo I d. C., cerca de la destrucción del Templo, y las diversas traducciones posteriores muestran ediciones adicionales, algunas de escribas cristianos." },
  "summary.lae.nt": { fp: "1csuspj", text: "Sus temas de los efectos duraderos de la caída sobre la humanidad y de la esperanza de restauración hacen eco de la discusión de Pablo sobre Adán y Cristo en Romanos 5. No tiene condición canónica, pero se leyó y se adaptó ampliamente." },
  "summary.lae.significance": { fp: "u7zrku", text: "El texto explica el sufrimiento humano, la enfermedad y la muerte como consecuencias del primer pecado, y a la vez ofrece esperanza de una resurrección final y de la restauración al paraíso." },
  "summary.life.authorship": { fp: "lrq3ce", text: "La autobiografía del propio Josefo, añadida a las Antigüedades y escrita en griego en la década del 90 d. C." },
  "summary.life.contents": { fp: "98j5bo", text: "Unas memorias en buena medida justificativas, centradas en su breve mando en Galilea al comienzo de la rebelión judía, donde defiende su lealtad, su competencia y sus intenciones frente a sus críticos." },
  "summary.life.context": { fp: "uqwzo1", text: "Se compuso en parte como autodefensa, en respuesta al relato rival de Justo de Tiberíades y a las acusaciones sobre la conducta de Josefo durante la rebelión." },
  "summary.life.nt": { fp: "oo1y7t", text: "Documenta con viveza el paisaje social y político de Galilea en la región misma y en la generación misma del ministerio de Jesús, con lo que ilumina el escenario de los Evangelios." },
  "summary.life.significance": { fp: "bjq7h4", text: "Más allá de su fin apologético, la obra ilustra la política fracturada de la Galilea del siglo I y la autopresentación moral de un personaje público antiguo." },
  "summary.odes-of-solomon.authorship": { fp: "1wfvpo8", text: "Un autor o unos autores desconocidos, probablemente de una comunidad judeocristiana siria, escribieron estos cuarenta y dos himnos, atribuidos falsamente a Salomón." },
  "summary.odes-of-solomon.contents": { fp: "3827s9", text: "Las odas expresan una devoción intensa con imágenes de luz, agua viva y amor, y celebran la unión con Dios y con el Cristo encarnado («el Verbo»), que desciende para liberar a los muertos y vuelve a ascender." },
  "summary.odes-of-solomon.context": { fp: "5hxvmw", text: "La mayoría de los especialistas fecha la colección a fines del siglo I o comienzos del II d. C., lo que la convierte en uno de los cuerpos de himnodia específicamente cristiana más antiguos que se conservan." },
  "summary.odes-of-solomon.nt": { fp: "uzg9la", text: "Aunque por razones de género se las clasifica técnicamente con la pseudoepigrafía judía, las Odas son en realidad un texto cristiano primitivo, y muestran una continuidad estrecha entre la poesía judía al modo de los salmos y la devoción cristiana naciente a Cristo. No tiene condición canónica." },
  "summary.odes-of-solomon.significance": { fp: "jy3yr8", text: "Las odas presentan una visión alta y mística de Cristo y usan imágenes marcadamente femeninas y maternas para Dios (como los «pechos» del Padre y la «leche» del Espíritu en la Oda 19), junto con la sensación de que el descanso y la luz eternos ya están presentes y no son solo futuros." },
  "summary.philo-abraham.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-abraham.contents": { fp: "ql48m3", text: "Una biografía de Abraham como modelo de la vida virtuosa, que lo presenta como quien alcanzó la sabiduría por naturaleza y por fe, con su historia leída a la vez en sentido literal y alegórico." },
  "summary.philo-abraham.context": { fp: "n21bwh", text: "La primera de las «biografías» de Filón, que presentan a los patriarcas como leyes vivientes." },
  "summary.philo-abraham.nt": { fp: "b2rrus", text: "El Abraham de Filón como modelo de la fe está al lado del retrato neotestamentario de Abraham como padre de todos los que creen (Romanos 4; Gálatas 3; Hebreos 11; Santiago 2)." },
  "summary.philo-abraham.significance": { fp: "u9wfkh", text: "Presenta a Abraham como la encarnación de la fe y la virtud: la «ley no escrita» que vivió la Torá antes de que fuera dada." },
  "summary.philo-alleg-interp.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-alleg-interp.contents": { fp: "19fknmo", text: "Un comentario alegórico, versículo por versículo, de Génesis 2–3, que trata a Adán, a Eva y al huerto como símbolos de la mente, de la percepción sensible y de la lucha del alma entre la virtud y el placer." },
  "summary.philo-alleg-interp.context": { fp: "h88q0a", text: "Escrito para lectores formados a la vez en la Torá y en la filosofía griega, en la Alejandría helenística." },
  "summary.philo-alleg-interp.nt": { fp: "1ndu419", text: "El método alegórico de Filón y su psicología de los «dos Adanes» y del conflicto interior del alma nutren la exégesis cristiana posterior y ofrecen trasfondo a los contrastes paulinos entre carne y espíritu." },
  "summary.philo-alleg-interp.significance": { fp: "1bnu67c", text: "Ejemplifica la convicción de Filón de que los relatos literales de la Escritura cifran verdades más hondas sobre el ascenso del alma hacia Dios y el dominio de las pasiones." },
  "summary.philo-cherubim.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-cherubim.contents": { fp: "qjk5aj", text: "Una exposición alegórica motivada por la expulsión del Edén y por los querubines que guardan el camino, que pasa luego al sentido de la espada llameante, a Caín y Abel y a las ofrendas del alma a Dios." },
  "summary.philo-cherubim.context": { fp: "17fijq6", text: "Compuesto dentro del programa alejandrino de leer a Moisés a través de la filosofía griega." },
  "summary.philo-cherubim.nt": { fp: "u5y6uw", text: "Su meditación sobre el culto aceptable e inaceptable y sobre las potencias de Dios aporta trasfondo conceptual a la reflexión neotestamentaria sobre el sacrificio verdadero y el falso." },
  "summary.philo-cherubim.significance": { fp: "18d5txl", text: "Interpreta el huerto custodiado como el alma a la que sus pasiones cierran el paraíso, y explora qué ofrendas son de verdad aceptables a Dios." },
  "summary.philo-confusion.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-confusion.contents": { fp: "1fjwszp", text: "Una lectura alegórica de Babel y de la confusión de las lenguas como la dispersión de un alma en rebeldía contra Dios, contrastada con el poder unificador del Logos divino." },
  "summary.philo-confusion.context": { fp: "104jbfw", text: "Interpreta el relato de Babel para un público alejandrino cosmopolita." },
  "summary.philo-confusion.nt": { fp: "1ib93ea", text: "El Logos filoniano que ordena y unifica, y su lectura de Babel, aportan trasfondo a la reversión de Babel en Pentecostés (Hechos 2) y a la teología neotestamentaria del Logos." },
  "summary.philo-confusion.significance": { fp: "p1gj87", text: "Trata la confusión de lenguas como imagen de la fragmentación que causa el orgullo, sanada por el Logos ordenador de Dios." },
  "summary.philo-congress.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-congress.contents": { fp: "1pnldr1", text: "Una alegoría de Abraham, Sara y Agar en la que Agar representa los estudios preliminares (gramática, retórica, geometría y semejantes) que preparan al alma para la sabiduría simbolizada por Sara." },
  "summary.philo-congress.context": { fp: "czbbm7", text: "Refleja el currículo educativo griego (la enkyklios paideia) como una etapa en la formación del alma." },
  "summary.philo-congress.nt": { fp: "wtkm82", text: "La alegoría filoniana de Sara y Agar como etapas superior e inferior ofrece una comparación llamativa con la alegoría, muy distinta, que Pablo hace de esas mismas mujeres en Gálatas 4." },
  "summary.philo-congress.significance": { fp: "99myxk", text: "Presenta el saber profano como una sierva legítima, pero preliminar, de la verdadera sabiduría y de la virtud." },
  "summary.philo-contemplative.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-contemplative.contents": { fp: "u1ud5a", text: "Una descripción de los terapeutas, comunidad judía contemplativa cercana a Alejandría, que elogia su vida ascética y orante de estudio de la Escritura, comidas sencillas y canto sagrado." },
  "summary.philo-contemplative.context": { fp: "tuewhe", text: "Describe una comunidad ascética real como ideal de la vida filosófico-religiosa." },
  "summary.philo-contemplative.nt": { fp: "f2h0e3", text: "La vida comunitaria, ascética y cultual de los terapeutas ofrece un trasfondo comparativo para la comunidad cristiana primitiva, las comidas comunes y el monacato posterior." },
  "summary.philo-contemplative.significance": { fp: "7bloao", text: "Recomienda el retiro, la contemplación y la meditación continua de la Escritura como la forma más alta de la vida devota." },
  "summary.philo-creation.authorship": { fp: "1i7lwug", text: "De Filón de Alejandría, el filósofo judío (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-creation.contents": { fp: "t04qei", text: "Una lectura filosófica de Génesis 1–3, que presenta el relato mosaico de la creación en armonía con el pensamiento platónico y estoico: el cosmos como obra de un Dios bueno, ordenado por el Logos divino, con la humanidad hecha a imagen divina." },
  "summary.philo-creation.context": { fp: "1rstnvj", text: "Filón pertenecía a la comunidad judía adinerada y muy helenizada de Alejandría, y buscaba mostrar que la Ley de Moisés concordaba con lo mejor de la filosofía griega." },
  "summary.philo-creation.nt": { fp: "1xoa0r5", text: "El Logos filoniano como agente y modelo de la creación constituye un trasfondo importante para el prólogo del Evangelio de Juan y para el lenguaje neotestamentario sobre Cristo como aquel por quien fueron hechas todas las cosas." },
  "summary.philo-creation.significance": { fp: "1crasp8", text: "Sostiene que el orden creado es racional y bueno porque procede de un Creador bueno por medio de su Logos, y que la mente humana lleva la imagen divina." },
  "summary.philo-decalogue.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-decalogue.contents": { fp: "1pvheti", text: "Una exposición de los Diez Mandamientos como los encabezados que resumen la Ley, con la explicación de por qué los dio Dios directamente y de cómo organizan todos los demás mandamientos." },
  "summary.philo-decalogue.context": { fp: "1r9mjuc", text: "Introduce la exposición sistemática que hace Filón de la ley mosaica para un público helenístico." },
  "summary.philo-decalogue.nt": { fp: "1sh4i8t", text: "El resumen filoniano de la Ley bajo el amor a Dios y al prójimo corre en paralelo con el resumen de los mandamientos que hace Jesús (Mateo 22) y con el de Pablo en Romanos 13." },
  "summary.philo-decalogue.significance": { fp: "v7apyg", text: "Trata el Decálogo como el fundamento pronunciado por Dios bajo el cual puede ordenarse cada ley particular, y une la piedad hacia Dios con la justicia hacia el prójimo." },
  "summary.philo-dreams.authorship": { fp: "10lj3fc", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego; dos libros conservados de una obra originalmente más extensa." },
  "summary.philo-dreams.contents": { fp: "190t41b", text: "Un tratado sobre los sueños enviados por Dios en la Escritura —la escala de Jacob y los sueños de José, del faraón y de otros—, clasificados e interpretados como encuentros del alma con lo divino." },
  "summary.philo-dreams.context": { fp: "12aj01c", text: "Dialoga con las teorías antiguas sobre los sueños y la adivinación desde un punto de vista judeofilosófico." },
  "summary.philo-dreams.nt": { fp: "2i6nof", text: "El tratamiento filoniano de los sueños reveladores y de la escala de Jacob como canal entre el cielo y la tierra ofrece trasfondo a las revelaciones oníricas de Mateo y a Juan 1:51." },
  "summary.philo-dreams.significance": { fp: "1u60qu7", text: "Presenta ciertos sueños como medios genuinos de comunicación divina, y lee la escala de Jacob como el ascenso del alma y el descenso de Dios." },
  "summary.philo-drunkenness.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-drunkenness.contents": { fp: "npd7h4", text: "Sobre el simbolismo del vino y de la embriaguez en la Escritura, distinguiendo la intoxicación insensata de la «embriaguez sobria» del alma arrebatada por Dios." },
  "summary.philo-drunkenness.context": { fp: "1cagy9p", text: "Se apoya tanto en la Escritura como en la literatura griega del simposio sobre el vino." },
  "summary.philo-drunkenness.nt": { fp: "1m75krf", text: "El contraste filoniano entre la embriaguez degradante y el éxtasis lleno del Espíritu ofrece trasfondo al «no se emborrachen con vino… antes bien sean llenos del Espíritu» de Pablo (Efesios 5:18) y a Pentecostés (Hechos 2)." },
  "summary.philo-drunkenness.significance": { fp: "16d5r6e", text: "Trata la embriaguez literal como imagen de la pérdida de razón del alma, mientras recomienda la extática «embriaguez sobria» de la contemplación." },
  "summary.philo-embassy.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-embassy.contents": { fp: "nrgx5f", text: "Describe la crisis por la exigencia de Calígula de ser adorado y por su plan de colocar su estatua en el templo de Jerusalén, y la peligrosa audiencia con el inestable emperador." },
  "summary.philo-embassy.context": { fp: "1849x49", text: "Un relato de primera mano de la embajada judía ante el emperador Gayo (Calígula) en los años 39–40 d. C., que el propio Filón encabezó." },
  "summary.philo-embassy.nt": { fp: "9ptrf3", text: "El choque entre el culto al César y la adoración exclusiva de Dios ilumina directamente la tensión neotestamentaria en torno al «César es señor» y el trasfondo del culto imperial en Apocalipsis." },
  "summary.philo-embassy.significance": { fp: "1inibah", text: "Retrata el enfrentamiento entre la adoración del único Dios y las pretensiones idolátricas del poder imperial, con confianza en la liberación de Dios." },
  "summary.philo-eternity.authorship": { fp: "4jtfns", text: "Atribuida a Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), aunque su autenticidad se discute." },
  "summary.philo-eternity.contents": { fp: "937ukk", text: "Un tratado filosófico que sostiene, en buena medida sobre bases estoicas y aristotélicas, que el mundo es increado e imperecedero: eterno en su existencia ordenada." },
  "summary.philo-eternity.context": { fp: "1fb7lzf", text: "Una pieza técnica que entra en el debate cosmológico griego entre estoicos, aristotélicos y platónicos." },
  "summary.philo-eternity.nt": { fp: "17jazzj", text: "Sus argumentos cosmológicos enmarcan la discusión antigua frente a la cual puede entenderse la expectativa neotestamentaria de cielos nuevos y tierra nueva (2 Pedro 3; Apocalipsis 21)." },
  "summary.philo-eternity.significance": { fp: "1pi8kw7", text: "Conserva argumentos antiguos sobre la permanencia del mundo, en tensión con la doctrina bíblica de la creación y la consumación (de ahí el debate sobre su autoría o su propósito)." },
  "summary.philo-flaccus.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-flaccus.contents": { fp: "12qiixg", text: "Una crónica de la persecución de los judíos de Alejandría bajo Flaco, que describe la violencia de las turbas y la complicidad oficial, y presenta la caída y el castigo del prefecto como prueba de la justicia divina." },
  "summary.philo-flaccus.context": { fp: "1r4moaf", text: "Un relato histórico de la violencia antijudía en Alejandría en el año 38 d. C., bajo el prefecto romano Aulo Avilio Flaco." },
  "summary.philo-flaccus.nt": { fp: "3spkkw", text: "Este testimonio de primera mano sobre la persecución antijudía y la administración provincial romana ilumina las presiones políticas y sociales que enfrentaron los judíos y, poco después, los cristianos en el imperio." },
  "summary.philo-flaccus.significance": { fp: "1t3n4br", text: "Interpreta teológicamente sucesos contemporáneos: Dios derriba al perseguidor y vindica a su pueblo, sosteniendo la providencia en medio del sufrimiento." },
  "summary.philo-flight.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-flight.contents": { fp: "1vbaqnx", text: "Sobre la huida de Agar y después la de Jacob, con los temas de huir, buscar y hallar, y con las ciudades de refugio como figuras del escape del alma frente a la pasión." },
  "summary.philo-flight.context": { fp: "1ao1v0g", text: "Continúa el ciclo de Abraham y Agar dentro de las alegorías de Filón sobre el Génesis." },
  "summary.philo-flight.nt": { fp: "19nn0m3", text: "Sus temas de buscar y hallar a Dios y de refugiarse de la culpa ofrecen trasfondo al lenguaje neotestamentario de buscar a Dios y hallar refugio en Cristo." },
  "summary.philo-flight.significance": { fp: "1x42z1o", text: "Traza los movimientos del alma que huye del vicio y persigue la virtud, y lee las ciudades de refugio como etapas de seguridad moral." },
  "summary.philo-fragments.authorship": { fp: "snb6b0", text: "Pasajes diversos atribuidos a Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que se conservan como citas en autores posteriores." },
  "summary.philo-fragments.contents": { fp: "1cepd9", text: "Una colección de fragmentos y extractos de obras filonianas perdidas o parciales, reunidos como apéndice." },
  "summary.philo-fragments.context": { fp: "k44x9r", text: "Una miscelánea reunida a partir de citas en los Padres de la Iglesia y en otras fuentes." },
  "summary.philo-fragments.nt": { fp: "d915x7", text: "Aportan material comparativo adicional para el mundo de ideas judeohelenístico del Nuevo Testamento." },
  "summary.philo-fragments.significance": { fp: "tuwhv2", text: "Los fragmentos conservan reflexiones filonianas sobre la Escritura, Dios y el alma que de otro modo se habrían perdido." },
  "summary.philo-giants.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-giants.contents": { fp: "17fwl5s", text: "Una lectura de Génesis 6 y de los «hijos de Dios» que interpreta a los ángeles, a los gigantes y al Espíritu de Dios en clave de almas, cuerpos y vida moral, y no como mito literal." },
  "summary.philo-giants.context": { fp: "sowx7p", text: "Aborda un pasaje desconcertante del Génesis para lectores que, de otro modo, tropezarían con su superficie mitológica." },
  "summary.philo-giants.nt": { fp: "nn6h7k", text: "El tratamiento filoniano de los «hijos de Dios», del Espíritu y de la vida atada a la carne ofrece trasfondo comparativo para la antropología neotestamentaria y para el uso que Judas y 2 Pedro hacen de la tradición de Génesis 6." },
  "summary.philo-giants.significance": { fp: "7gxc06", text: "Distingue las almas entregadas a Dios de las enredadas en la carne, y reflexiona sobre cómo el Espíritu divino habita con los seres humanos." },
  "summary.philo-good-person.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-good-person.contents": { fp: "echusf", text: "Una defensa filosófica de la paradoja estoica de que solo el hombre moralmente bueno es verdaderamente libre, ilustrada con ejemplos que incluyen una notable descripción de los esenios." },
  "summary.philo-good-person.context": { fp: "7ebtc4", text: "Un ensayo filosófico que defiende una tesis estoica bien conocida, con ejemplos judíos." },
  "summary.philo-good-person.nt": { fp: "v9pczn", text: "Su exposición de la libertad interior en medio de la esclavitud exterior corre en paralelo con las paradojas paulinas de libertad y servidumbre en Cristo (1 Corintios 7; Romanos 6), y su descripción de los esenios ilumina el mundo sectario judío del Nuevo Testamento." },
  "summary.philo-good-person.significance": { fp: "1h1rmvu", text: "Sitúa la libertad verdadera en la virtud y en el dominio interior, y no en la circunstancia externa, y valora al sabio que es libre aun encadenado." },
  "summary.philo-heir.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-heir.contents": { fp: "5r84bk", text: "Una exposición de la promesa del pacto de Dios a Abraham (Génesis 15), sobre quién es apto para ser «heredero» de las cosas divinas y sobre la división del sacrificio como lección acerca del ordenamiento del cosmos." },
  "summary.philo-heir.context": { fp: "60nka2", text: "Expone en términos filosóficos la escena del pacto de Génesis 15." },
  "summary.philo-heir.nt": { fp: "z7tk6w", text: "La meditación filoniana sobre la fe de Abraham que «le fue contada» y sobre la herencia divina ilumina el argumento de Pablo en Romanos y Gálatas y el lenguaje de los «herederos de la promesa» en Hebreos." },
  "summary.philo-heir.significance": { fp: "1z11gpl", text: "Enseña que el verdadero heredero de Dios es el alma que confía en Dios y no en sí misma, y lee el mundo como dividido en opuestos equilibrados que el Logos mantiene unidos." },
  "summary.philo-husbandry.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-husbandry.contents": { fp: "yf4mv6", text: "Una alegoría construida sobre Noé como «labrador», que contrasta el cultivo experto de las virtudes del alma con la mera faena sin oficio." },
  "summary.philo-husbandry.context": { fp: "19sttqe", text: "Parte de la exposición alegórica que hace Filón del relato de Noé." },
  "summary.philo-husbandry.nt": { fp: "w1b3hz", text: "Las imágenes agrícolas del crecimiento espiritual corren en paralelo con las parábolas de Jesús sobre la siembra y el cultivo y con el lenguaje paulino de plantar, regar y dar fruto." },
  "summary.philo-husbandry.significance": { fp: "1hqwhdu", text: "Presenta el progreso moral como el cultivo paciente del alma, y distingue al verdadero «agricultor» de la virtud del jornalero sin rumbo." },
  "summary.philo-hypothetica.authorship": { fp: "192rxid", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego; se conserva solo en fragmentos citados por Eusebio." },
  "summary.philo-hypothetica.contents": { fp: "1iapy71", text: "Una apología (defensa) que resume la historia de Israel y la excelencia de sus costumbres y leyes, e incluye otra descripción de los esenios." },
  "summary.philo-hypothetica.context": { fp: "y9p7w8", text: "Una obra apologética que defiende al pueblo judío y sus leyes ante un público grecorromano escéptico u hostil." },
  "summary.philo-hypothetica.nt": { fp: "1pwabdf", text: "Como apologética judía temprana, ejemplifica el tipo de defensa de la fe ante los de fuera que también emprende el Nuevo Testamento (Hechos; 1 Pedro 3:15)." },
  "summary.philo-hypothetica.significance": { fp: "1dogobw", text: "Recomienda la sabiduría, la humanidad y la cohesión social de la ley judía frente a las críticas paganas." },
  "summary.philo-joseph.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-joseph.contents": { fp: "w8y744", text: "Un retrato de José como estadista ideal, que se sirve de su ascenso en Egipto para reflexionar sobre la vida política, el dominio de sí y el gobierno de un alma y de una sociedad bien ordenadas." },
  "summary.philo-joseph.context": { fp: "1hkzc3u", text: "Reflexiona sobre el arte ideal de gobernar, en un tratado dirigido en parte a un público de inquietudes políticas." },
  "summary.philo-joseph.nt": { fp: "mhmnfg", text: "Sus temas de la providencia que torna el mal en bien y del justo que sufre y es exaltado para salvar a otros corren en paralelo con los ecos de la historia de José en Hechos 7 y con la teología neotestamentaria de la providencia." },
  "summary.philo-joseph.significance": { fp: "11l38fr", text: "Recomienda al gobernante sabio y dueño de sí, que gobierna a los demás como se gobierna a sí mismo, bajo la providencia de Dios." },
  "summary.philo-migration.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-migration.contents": { fp: "fgb2kf", text: "Sobre el llamado a Abraham a dejar su tierra, su parentela y la casa de su padre (Génesis 12), leído como el viaje del alma que se aparta del cuerpo y de los sentidos hacia Dios." },
  "summary.philo-migration.context": { fp: "wq9j3r", text: "Parte del ciclo filoniano sobre Abraham como arquetipo del alma que busca." },
  "summary.philo-migration.nt": { fp: "1k3ghjo", text: "El Abraham filoniano que camina por fe hacia una meta no vista corre muy en paralelo con el retrato de Abraham en Romanos 4 y en Hebreos 11." },
  "summary.philo-migration.significance": { fp: "15hywrd", text: "Presenta la vida de fe como una peregrinación en la que el alma abandona apegos menores para buscar la visión de Dios." },
  "summary.philo-moses.authorship": { fp: "j01d5w", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego; en dos libros." },
  "summary.philo-moses.contents": { fp: "il8gw2", text: "Una vida de Moisés que lo presenta como rey, legislador, sacerdote y profeta perfecto, y que reúne su historia en un retrato idealizado del fundador de Israel." },
  "summary.philo-moses.context": { fp: "87lx1r", text: "Escrita en parte para lectores no judíos, a fin de recomendar a Moisés y la ley judía al mundo grecorromano más amplio." },
  "summary.philo-moses.nt": { fp: "1t59avf", text: "El Moisés cuádruple de Filón (rey, legislador, sacerdote, profeta) ofrece una comparación llamativa con la presentación neotestamentaria de Cristo como profeta, sacerdote y rey, y con su tipología Moisés-Cristo (Juan; Hebreos)." },
  "summary.philo-moses.significance": { fp: "drtq9g", text: "Eleva a Moisés como mediador supremo entre Dios y la humanidad y como modelo de todo oficio noble." },
  "summary.philo-names.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-names.contents": { fp: "1a8qe64", text: "Sobre el cambio de nombre de Abram a Abraham y de Sarai a Sara; lee el cambio de nombres como marca de las etapas del avance del alma hacia la virtud y el conocimiento de Dios." },
  "summary.philo-names.context": { fp: "zyf26r", text: "Refleja el interés antiguo por el significado de los nombres como señales de carácter y de destino." },
  "summary.philo-names.nt": { fp: "1gu3xwn", text: "El motivo del nombre nuevo que marca una identidad nueva ante Dios resuena con los cambios de nombre neotestamentarios (Simón/Pedro) y con el «nombre nuevo» de Apocalipsis 2–3." },
  "summary.philo-names.significance": { fp: "kz2ute", text: "Trata la imposición de nombres nuevos como signo de transformación y de elección divina, y rastrea el avance del alma hacia la madurez." },
  "summary.philo-planter.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-planter.contents": { fp: "x0a9dc", text: "Sobre Noé, plantador de una viña; lee la plantación de árboles como el cultivo que Dios hace de la virtud en el mundo y en el alma." },
  "summary.philo-planter.context": { fp: "psfhq2", text: "Obra hermana de Sobre la agricultura, dentro del ciclo alegórico de Noé." },
  "summary.philo-planter.nt": { fp: "1irmshi", text: "Su imagen de Dios como plantador y del alma como su terreno cultivado ilumina las imágenes de la vid y de la viña en Juan 15 y en las parábolas sinópticas." },
  "summary.philo-planter.significance": { fp: "1cvsg3l", text: "Presenta a Dios como el plantador supremo que cultiva la bondad, y advierte contra la embriaguez que arruina la viña del alma." },
  "summary.philo-posterity.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-posterity.contents": { fp: "1pc80ls", text: "Un tratamiento alegórico de los descendientes de Caín y de su destierro, que explora qué significa «salir de la presencia de Dios» y la esterilidad de una vida separada de lo divino." },
  "summary.philo-posterity.context": { fp: "slh02w", text: "Continúa la lectura alegórica alejandrina de los primeros capítulos del Génesis." },
  "summary.philo-posterity.nt": { fp: "10geo8g", text: "Su cuadro del destierro lejos de la presencia de Dios como muerte espiritual corre en paralelo con el lenguaje neotestamentario de estar «alejados de Dios» y ser reconciliados en Cristo." },
  "summary.philo-posterity.significance": { fp: "1ruolxu", text: "Retrata el extrañamiento de Dios como el destierro más hondo y como la fuente de la futilidad de una vida, y lo contrasta con la fecundidad de la comunión con Dios." },
  "summary.philo-providence.authorship": { fp: "neagxo", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego; se conserva sobre todo en armenio y en fragmentos griegos." },
  "summary.philo-providence.contents": { fp: "u5svno", text: "Una defensa de la providencia divina frente a las objeciones, que sostiene que Dios gobierna el mundo con justicia pese a la aparente prosperidad de los malvados y al sufrimiento de los buenos." },
  "summary.philo-providence.context": { fp: "8gc4om", text: "Un diálogo que entra en el debate filosófico griego sobre si el mundo lo gobierna la providencia o el azar." },
  "summary.philo-providence.nt": { fp: "mr72k7", text: "Su defensa de la providencia en medio de la aparente injusticia corre en paralelo con la seguridad neotestamentaria de que Dios hace que todo obre para bien (Romanos 8:28) y con su forcejeo con la teodicea." },
  "summary.philo-providence.significance": { fp: "1urshar", text: "Sostiene que un Dios sabio y bueno ordena todas las cosas, y aborda el problema del mal con argumentos tomados de la Escritura y de la filosofía." },
  "summary.philo-qg.authorship": { fp: "l7rkjx", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego; se conserva en buena parte en armenio." },
  "summary.philo-qg.contents": { fp: "ywx93l", text: "Un comentario continuo al Génesis en forma de preguntas y respuestas, que da explicaciones literales y alegóricas del texto versículo por versículo." },
  "summary.philo-qg.context": { fp: "1ib7t5j", text: "Un comentario erudito en el formato de preguntas y respuestas, común en la exégesis antigua." },
  "summary.philo-qg.nt": { fp: "1cmziy8", text: "Su exégesis detallada del Génesis aporta trasfondo comparativo para la interpretación neotestamentaria y cristiana primitiva de esos mismos relatos." },
  "summary.philo-qg.significance": { fp: "1pamnc4", text: "Muestra el método de Filón para extraer sentido moral y filosófico de cada detalle del texto sagrado." },
  "summary.philo-rewards.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-rewards.contents": { fp: "jy9ch9", text: "Sobre las recompensas prometidas a los buenos y los castigos que aguardan a los malvados; termina con bendiciones y maldiciones y con la esperanza de la restauración de Israel." },
  "summary.philo-rewards.context": { fp: "1sww8ut", text: "Cierra la exposición filoniana de la Ley con sus sanciones." },
  "summary.philo-rewards.nt": { fp: "1yui01j", text: "Su marco de bendiciones y maldiciones y su esperanza de restauración corren en paralelo con la lógica del pacto que está detrás de las advertencias y promesas del Nuevo Testamento y de la esperanza de la salvación de Israel (Romanos 9–11)." },
  "summary.philo-rewards.significance": { fp: "lbulzb", text: "Afirma que el orden moral de Dios sostiene la historia, recompensando la virtud y el arrepentimiento esperanzado, y prometiendo la reunión final de su pueblo." },
  "summary.philo-sacrifices.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-sacrifices.contents": { fp: "1rjdp9q", text: "Una alegoría de Caín y Abel como dos disposiciones del alma —el amor propio frente a la entrega a Dios—, con una reflexión sobre por qué Dios aceptó una ofrenda y rechazó la otra." },
  "summary.philo-sacrifices.context": { fp: "1pmttzq", text: "Parte del comentario alegórico continuo de Filón al Génesis, para un público judío helenizado." },
  "summary.philo-sacrifices.nt": { fp: "cauany", text: "Su lectura de Caín y Abel como principios rivales anticipa la tipología moral de los dos hermanos que se halla en Hebreos, en 1 Juan y en Judas." },
  "summary.philo-sacrifices.significance": { fp: "wuryc2", text: "El tratado enseña que Dios mira la disposición del oferente y no el don exterior, y que valora la entrega de todo corazón por encima de la religión interesada." },
  "summary.philo-sobriety.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-sobriety.contents": { fp: "7ux43o", text: "Sobre la sobriedad de Noé después del vino, sobre la bendición y la maldición de Sem, Cam y Jafet, y sobre la sabiduría de la mente despierta y dueña de sí." },
  "summary.philo-sobriety.context": { fp: "3p1pxu", text: "Una secuela breve dentro de las alegorías de Noé." },
  "summary.philo-sobriety.nt": { fp: "prdhn5", text: "Su elogio del dominio propio vigilante corre en paralelo con las exhortaciones neotestamentarias a ser «sobrios y velar» (1 Tesalonicenses 5; 1 Pedro 5)." },
  "summary.philo-sobriety.significance": { fp: "16cja6i", text: "Recomienda el dominio de sí y la sabiduría lúcida del alma sobria, y lee las bendiciones y maldiciones como tipos morales." },
  "summary.philo-spec-laws.authorship": { fp: "854pma", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego; en cuatro libros." },
  "summary.philo-spec-laws.contents": { fp: "po5fqc", text: "Un tratamiento sistemático de las leyes particulares de Moisés, ordenadas bajo los Diez Mandamientos, que abarca el culto, los juramentos, el sábado y las fiestas, el matrimonio y la familia, la justicia y las virtudes." },
  "summary.philo-spec-laws.context": { fp: "q5svqn", text: "La pieza central de la presentación sistemática que hace Filón de la legislación mosaica." },
  "summary.philo-spec-laws.nt": { fp: "vfug5x", text: "La justificación filoniana del fin ético de la ley y su insistencia en la intención interior de esta iluminan los debates neotestamentarios sobre el sentido y el cumplimiento de la ley." },
  "summary.philo-spec-laws.significance": { fp: "gwj7tk", text: "Sostiene que la ley detallada es racional, humana y ordenada a la virtud, y muestra la Torá como un sistema moral y espiritual coherente." },
  "summary.philo-unchangeable.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-unchangeable.contents": { fp: "51hswf", text: "A propósito de Génesis 6:4–12, un argumento de que Dios no «se arrepiente» ni cambia, y de que el lenguaje bíblico sobre las emociones divinas es una acomodación al entendimiento humano." },
  "summary.philo-unchangeable.context": { fp: "w9kehb", text: "Escrito para defender una doctrina de Dios filosóficamente refinada frente a una lectura ingenua de la Escritura." },
  "summary.philo-unchangeable.nt": { fp: "1pdpn8w", text: "La exposición filoniana de la constancia divina y del hablar acomodado sobre Dios está detrás de la reflexión cristiana sobre la fidelidad inmutable de Dios (p. ej., Santiago 1:17; Hebreos 6:17–18)." },
  "summary.philo-unchangeable.significance": { fp: "1xufilj", text: "Articula la inmutabilidad divina y el principio de que el lenguaje antropomórfico sobre Dios es condescendencia con la debilidad humana, un paso fundacional en la teología posterior." },
  "summary.philo-virtues.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-virtues.contents": { fp: "qaant2", text: "Una exposición de las virtudes que fomenta la ley mosaica —valor, humanidad (filantropía), arrepentimiento y nobleza—, que muestra la Ley como escuela de carácter ético." },
  "summary.philo-virtues.context": { fp: "1b6vh5l", text: "Redondea la exposición filoniana de la Ley destacando las virtudes que fomenta." },
  "summary.philo-virtues.nt": { fp: "obaw0k", text: "El relieve que da al arrepentimiento (metanoia) y al amor al prójimo como virtudes centrales resuena con fuerza en la enseñanza ética de los Evangelios y de las epístolas." },
  "summary.philo-virtues.significance": { fp: "c109kj", text: "Presenta la Torá como formadora de un pueblo compasivo, valiente y dispuesto al arrepentimiento, con un acento especial en la bondad hacia los vulnerables y en la posibilidad de conversión." },
  "summary.philo-world.authorship": { fp: "2mojpa", text: "Una breve pieza cosmológica transmitida en el corpus filoniano; su autenticidad es incierta." },
  "summary.philo-world.contents": { fp: "1yxp0ro", text: "Una exposición breve de la estructura y el ordenamiento del mundo físico." },
  "summary.philo-world.context": { fp: "1mqjrej", text: "Un tratado suplementario añadido a la colección, de origen discutido." },
  "summary.philo-world.nt": { fp: "9kka24", text: "Ofrece trasfondo a la cosmología antigua que da por supuesta el lenguaje neotestamentario sobre la creación." },
  "summary.philo-world.significance": { fp: "1j0b08q", text: "Refleja la reflexión antigua sobre el cosmos como un todo ordenado." },
  "summary.philo-worse.authorship": { fp: "1biwx8g", text: "De Filón de Alejandría (c. 20 a. C. – c. 50 d. C.), que escribe en griego." },
  "summary.philo-worse.contents": { fp: "8dlfvc", text: "Una continuación sobre Caín y Abel que sostiene que el amante de sí mismo (el «peor») ataca al amante de Dios (el «mejor»), pero no puede destruir de verdad la virtud." },
  "summary.philo-worse.context": { fp: "17l8w05", text: "Una secuela dentro de las alegorías filonianas del Génesis, dirigida a lectores versados en la ética griega." },
  "summary.philo-worse.nt": { fp: "myhflm", text: "Su confianza en que la vida que ama a Dios no puede ser vencida al final resuena con las seguridades neotestamentarias de que nada puede separar a los fieles de Dios." },
  "summary.philo-worse.significance": { fp: "14nq9yf", text: "Afirma que la virtud genuina, arraigada en Dios, es en último término invulnerable a los ataques del vicio." },
  "summary.pseudo-philo.authorship": { fp: "pafa7m", text: "Una nueva narración de la historia bíblica atribuida erróneamente a Filón (de ahí «Pseudo-Filón»), de un autor judío anónimo del siglo I d. C.; se la llama también Antigüedades bíblicas (L. A. B.)." },
  "summary.pseudo-philo.contents": { fp: "5fdyk4", text: "Una Biblia reescrita que va de Adán a David y llena los vacíos con relatos ampliados, discursos y leyendas, sobre todo acerca de los jueces y de figuras como Cenaz y la hija de Jefté." },
  "summary.pseudo-philo.context": { fp: "1d5br6e", text: "Escrita en Palestina hacia la época del Nuevo Testamento, atestigua cómo se volvía a contar y a ampliar la Escritura en el judaísmo del siglo I." },
  "summary.pseudo-philo.nt": { fp: "16wxrpp", text: "Como «Biblia reescrita» del siglo I, ilumina los métodos y las tradiciones interpretativas que compartían los autores del Nuevo Testamento." },
  "summary.pseudo-philo.significance": { fp: "1utumm9", text: "Subraya la fidelidad de Dios al pacto, el papel de los líderes y la certeza del juicio y de la recompensa divinos." },
  "summary.sibylline-greek.authorship": { fp: "tm1bi", text: "Es una colección mixta de doce libros de poesía profética griega, escrita por distintos autores desconocidos, judíos primero y cristianos después, a lo largo de varios siglos, todos ellos fingiendo ser las palabras de la profetisa pagana llamada la Sibila." },
  "summary.sibylline-greek.contents": { fp: "7az3x4", text: "Los oráculos predicen el juicio de las naciones, condenan el culto a los ídolos y la inmoralidad, y aguardan una edad de oro venidera o un reino mesiánico; las secciones cristianas posteriores añaden referencias explícitas a Jesús." },
  "summary.sibylline-greek.context": { fp: "za1yoh", text: "El material va del siglo II a. C. (las secciones más antiguas y claramente judías) hasta los siglos IV o V d. C. en sus capas cristianas posteriores, y comenta por el camino sucesos políticos reales, como las conquistas romanas." },
  "summary.sibylline-greek.nt": { fp: "1lixj93", text: "Escritores cristianos primitivos como Justino Mártir citaron los Oráculos como prueba pagana e independiente de las afirmaciones cristianas. La colección nunca fue Escritura en ninguna tradición, pero fue influyente en la apologética." },
  "summary.sibylline-greek.significance": { fp: "7mm9g9", text: "Al poner una enseñanza monoteísta y ética en boca de una profetisa pagana respetada, los autores judíos y cristianos intentaron mostrar que hasta los de fuera podían confirmar la verdad bíblica." },
  "summary.sibylline.authorship": { fp: "tm1bi", text: "Es una colección mixta de doce libros de poesía profética griega, escrita por distintos autores desconocidos, judíos primero y cristianos después, a lo largo de varios siglos, todos ellos fingiendo ser las palabras de la profetisa pagana llamada la Sibila." },
  "summary.sibylline.contents": { fp: "7az3x4", text: "Los oráculos predicen el juicio de las naciones, condenan el culto a los ídolos y la inmoralidad, y aguardan una edad de oro venidera o un reino mesiánico; las secciones cristianas posteriores añaden referencias explícitas a Jesús." },
  "summary.sibylline.context": { fp: "za1yoh", text: "El material va del siglo II a. C. (las secciones más antiguas y claramente judías) hasta los siglos IV o V d. C. en sus capas cristianas posteriores, y comenta por el camino sucesos políticos reales, como las conquistas romanas." },
  "summary.sibylline.nt": { fp: "1lixj93", text: "Escritores cristianos primitivos como Justino Mártir citaron los Oráculos como prueba pagana e independiente de las afirmaciones cristianas. La colección nunca fue Escritura en ninguna tradición, pero fue influyente en la apologética." },
  "summary.sibylline.significance": { fp: "7mm9g9", text: "Al poner una enseñanza monoteísta y ética en boca de una profetisa pagana respetada, los autores judíos y cristianos intentaron mostrar que hasta los de fuera podían confirmar la verdad bíblica." },
  "summary.testament-of-abraham-a.authorship": { fp: "1dy8jdc", text: "Un autor desconocido, que probablemente escribía en Egipto, compuso este testamento de humor poco común." },
  "summary.testament-of-abraham-a.contents": { fp: "kfzaf3", text: "Abraham se niega tercamente a morir cuando el ángel de la muerte (Miguel) viene por él; recorre el cielo, contempla el juicio de las almas y por fin se lo llevan con una argucia." },
  "summary.testament-of-abraham-a.context": { fp: "1vmsx23", text: "La mayoría de los especialistas lo fecha en los siglos I o II d. C. y lo considera sustancialmente judío, aunque se discute el grado de edición cristiana posterior." },
  "summary.testament-of-abraham-a.nt": { fp: "118dygm", text: "Su retrato cómico y humano de la resistencia a morir ofrece una meditación accesible sobre la mortalidad junto con la confianza en la misericordia divina, tema que tiene ecos en el lenguaje neotestamentario de consuelo ante la muerte. No tiene condición canónica." },
  "summary.testament-of-abraham-a.significance": { fp: "1o5ezmp", text: "El texto es de tono notablemente universalista: las almas cuyas obras buenas y malas están en equilibrio reciben una consideración misericordiosa especial, con lo que se subraya la compasión de Dios junto a su justicia." },
  "summary.testament-of-abraham-b.authorship": { fp: "1dy8jdc", text: "Un autor desconocido, que probablemente escribía en Egipto, compuso este testamento de humor poco común." },
  "summary.testament-of-abraham-b.contents": { fp: "kfzaf3", text: "Abraham se niega tercamente a morir cuando el ángel de la muerte (Miguel) viene por él; recorre el cielo, contempla el juicio de las almas y por fin se lo llevan con una argucia." },
  "summary.testament-of-abraham-b.context": { fp: "1vmsx23", text: "La mayoría de los especialistas lo fecha en los siglos I o II d. C. y lo considera sustancialmente judío, aunque se discute el grado de edición cristiana posterior." },
  "summary.testament-of-abraham-b.nt": { fp: "118dygm", text: "Su retrato cómico y humano de la resistencia a morir ofrece una meditación accesible sobre la mortalidad junto con la confianza en la misericordia divina, tema que tiene ecos en el lenguaje neotestamentario de consuelo ante la muerte. No tiene condición canónica." },
  "summary.testament-of-abraham-b.significance": { fp: "1o5ezmp", text: "El texto es de tono notablemente universalista: las almas cuyas obras buenas y malas están en equilibrio reciben una consideración misericordiosa especial, con lo que se subraya la compasión de Dios junto a su justicia." },
  "summary.testament-of-solomon.authorship": { fp: "1hbpjmc", text: "Un autor desconocido escribió este texto en la voz de Salomón; superpone tradición mágica judía y grecoegipcia anterior bajo una edición cristiana posterior y muy marcada." },
  "summary.testament-of-solomon.contents": { fp: "1mbpd57", text: "Salomón recibe del arcángel Miguel un anillo mágico que le permite mandar a los demonios, y el texto enumera muchos demonios junto con los nombres o las acciones angélicas que los vencen; termina con la caída de Salomón por la idolatría." },
  "summary.testament-of-solomon.context": { fp: "na4dua", text: "Su fecha se discute mucho, entre los siglos I y IV d. C., lo que refleja un largo proceso de crecimiento y reescritura." },
  "summary.testament-of-solomon.nt": { fp: "1ro0pb1", text: "Esta demonología detallada ayuda a explicar los presupuestos que hay detrás de los relatos evangélicos de exorcismo, donde Jesús y sus seguidores expulsan demonios entendidos en términos semejantes. No tiene condición canónica." },
  "summary.testament-of-solomon.significance": { fp: "1noodpi", text: "El texto sistematiza la demonología, empareja demonios concretos con enfermedades o vicios concretos y ángeles concretos con su derrota, y refleja una cosmovisión en la que los espíritus malignos causan activamente el sufrimiento." },
  "summary.tg-isaiah.authorship": { fp: "af6e13", text: "El Targum arameo (traducción interpretativa) de Isaías, parte del Targum oficial de los Profetas (Targum Jonatán); sus tradiciones se remontan a los primeros siglos de nuestra era." },
  "summary.tg-isaiah.contents": { fp: "3p3nbt", text: "Una versión aramea amplificada de Isaías para la sinagoga, que parafrasea e interpreta mientras traduce, y que desarrolla notablemente lecturas mesiánicas de pasajes clave." },
  "summary.tg-isaiah.context": { fp: "1i68v0r", text: "Los targumim surgieron para verter las Escrituras hebreas al arameo ante los auditorios de la sinagoga, y mezclan traducción con interpretación." },
  "summary.tg-isaiah.nt": { fp: "18njqfo", text: "Sus versiones mesiánicas (p. ej., de los pasajes del siervo) iluminan cómo leían a Isaías los judíos del siglo I y aportan trasfondo al uso que el Nuevo Testamento hace del profeta." },
  "summary.tg-isaiah.significance": { fp: "1q8c8gu", text: "Muestra cómo se oía y se entendía a Isaías en la sinagoga, y a menudo hace explícitos sentidos mesiánicos y teológicos implícitos." },
  "summary.tg-psj-deuteronomy.authorship": { fp: "2zrhq0", text: "Targum Pseudo-Jonatán (paráfrasis aramea amplificada de la Torá)." },
  "summary.tg-psj-deuteronomy.contents": { fp: "wwxxue", text: "Un Deuteronomio arameo amplificado que parafrasea los discursos y las leyes de Moisés con añadidos interpretativos." },
  "summary.tg-psj-deuteronomy.context": { fp: "woh6vx", text: "Vierte los discursos finales de Moisés para la sinagoga." },
  "summary.tg-psj-deuteronomy.nt": { fp: "1ba9m3p", text: "Su versión del Shemá y de los temas del pacto ilumina la lectura judía que está detrás del uso que Jesús y Pablo hacen del Deuteronomio." },
  "summary.tg-psj-deuteronomy.significance": { fp: "mhmsna", text: "Subraya la lealtad al pacto y el amor de Dios en el corazón de la Torá." },
  "summary.tg-psj-exodus.authorship": { fp: "oehuzw", text: "Targum Pseudo-Jonatán (paráfrasis aramea amplificada de la Torá), que alcanzó su forma actual en el período medieval temprano sobre fundamentos anteriores." },
  "summary.tg-psj-exodus.contents": { fp: "1dyi6xy", text: "Un Éxodo arameo amplificado, que añade ampliaciones narrativas y legales al relato del éxodo, del Sinaí y del tabernáculo." },
  "summary.tg-psj-exodus.context": { fp: "ky7fjp", text: "Parte de la tradición sinagogal aramea de verter la Torá." },
  "summary.tg-psj-exodus.nt": { fp: "1jiwx0g", text: "Sus ampliaciones sobre el éxodo y el Sinaí iluminan la tradición judía posterior sobre temas que el Nuevo Testamento reelabora en torno a Cristo." },
  "summary.tg-psj-exodus.significance": { fp: "1yi2tx0", text: "Desarrolla el sentido teológico y legal de la liberación y de la entrega de la ley fundacionales de Israel." },
  "summary.tg-psj-genesis.authorship": { fp: "jfsm6g", text: "Targum Pseudo-Jonatán, paráfrasis aramea amplificada de la Torá, compilada a lo largo de siglos y que alcanzó su forma actual en el período medieval temprano, aunque se apoya en tradiciones muy anteriores." },
  "summary.tg-psj-genesis.contents": { fp: "1hbarjc", text: "Un Génesis arameo ricamente ampliado, que entreteje leyendas midrásicas, detalles haláquicos y comentario interpretativo en el relato que va de la creación a José." },
  "summary.tg-psj-genesis.context": { fp: "185zlcx", text: "Conserva una rica corriente de tradición interpretativa judía (midrás y halajá) adherida al texto bíblico." },
  "summary.tg-psj-genesis.nt": { fp: "192u3k2", text: "Sus ampliaciones interpretativas ofrecen material comparativo para entender la lectura judía del Génesis, parte de la cual corre en paralelo con tradiciones que resuenan en el Nuevo Testamento." },
  "summary.tg-psj-genesis.significance": { fp: "14qflni", text: "Revela cómo se exponían y se aplicaban los relatos del Génesis dentro de la tradición judía posterior." },
  "summary.tg-psj-leviticus.authorship": { fp: "2zrhq0", text: "Targum Pseudo-Jonatán (paráfrasis aramea amplificada de la Torá)." },
  "summary.tg-psj-leviticus.contents": { fp: "10e9czi", text: "Un Levítico arameo interpretativo que elabora las leyes de sacrificio y de pureza con detalle haláquico." },
  "summary.tg-psj-leviticus.context": { fp: "4pr8al", text: "Vierte la legislación sacerdotal para que se entienda en la sinagoga." },
  "summary.tg-psj-leviticus.nt": { fp: "n8ci53", text: "Su tratamiento del sacrificio y de la pureza aporta trasfondo comparativo a la reflexión neotestamentaria sobre la expiación y la santidad." },
  "summary.tg-psj-leviticus.significance": { fp: "cfrxwo", text: "Aclara y aplica el sistema de santidad y de sacrificios dentro de la tradición legal judía." },
  "summary.tg-psj-numbers.authorship": { fp: "2zrhq0", text: "Targum Pseudo-Jonatán (paráfrasis aramea amplificada de la Torá)." },
  "summary.tjob-greek.authorship": { fp: "3o5x5w", text: "Un autor desconocido amplió el libro bíblico de Job hasta convertirlo en este relato más extenso, al modo de un testamento." },
  "summary.tjob-greek.contents": { fp: "1chlthm", text: "Job, moribundo, cuenta a sus hijos su paciente perseverancia bajo el ataque demoníaco (con Satanás como enemigo activo) y el culto extático de sus tres hijas después de recibir dones místicos de su padre." },
  "summary.tjob-greek.context": { fp: "1gwwlgc", text: "La mayoría de los especialistas lo fecha en el siglo I a. C. o d. C., posiblemente ligado a una comunidad judía ascética egipcia semejante a los terapeutas que describe Filón." },
  "summary.tjob-greek.nt": { fp: "b9rqoj", text: "Su insistencia en la perseverancia paciente bajo el sufrimiento corre en paralelo con la enseñanza neotestamentaria (como en Santiago 5:11, que elogia expresamente la paciencia de Job). No tiene condición canónica." },
  "summary.tjob-greek.significance": { fp: "ujwgd6", text: "El texto reformula a Job sobre todo como modelo de perseverancia paciente, más que como el Job discutidor y preguntón de la Biblia, y muestra interés por la experiencia espiritual mística." },
  "summary.tp-asher.authorship": { fp: "1dg6y0w", text: "De los Testamentos de los Doce Patriarcas (judíos, con edición cristiana)." },
  "summary.tp-asher.contents": { fp: "1hpqbzs", text: "Aser contrasta los «dos caminos» de la virtud y del vicio y advierte contra la hipocresía de doble cara." },
  "summary.tp-asher.context": { fp: "7yivzv", text: "Se sirve de la tradición de los «dos caminos» de instrucción ética." },
  "summary.tp-asher.nt": { fp: "1s4ubkw", text: "Sus «dos caminos» y su advertencia contra la doblez corren en paralelo con el Sermón del Monte, la Didajé y Santiago." },
  "summary.tp-asher.significance": { fp: "1tev74z", text: "Llama a una bondad sin dobleces y desenmascara el peligro de una vida dividida e hipócrita." },
  "summary.tp-benjamin.authorship": { fp: "1dg6y0w", text: "De los Testamentos de los Doce Patriarcas (judíos, con edición cristiana)." },
  "summary.tp-benjamin.contents": { fp: "1bn6v0b", text: "Benjamín elogia la «mente pura», urge a sus hijos hacia la bondad y señala hacia una redención venidera." },
  "summary.tp-benjamin.context": { fp: "49g6ry", text: "Cierra la colección con un llamado a la pureza de mente y a la esperanza futura." },
  "summary.tp-benjamin.nt": { fp: "paoz0r", text: "Su ideal del «corazón puro» resuena con la bienaventuranza «dichosos los de limpio corazón» (Mateo 5:8)." },
  "summary.tp-benjamin.significance": { fp: "19pq7ug", text: "Recomienda la pureza interior y la buena disposición que ve el bien en todas las cosas." },
  "summary.tp-dan.authorship": { fp: "1dg6y0w", text: "De los Testamentos de los Doce Patriarcas (judíos, con edición cristiana)." },
  "summary.tp-dan.contents": { fp: "trhqc3", text: "Dan advierte contra la ira y la mentira y exhorta a sus hijos a amar la verdad y al Señor." },
  "summary.tp-dan.context": { fp: "uauvxi", text: "Advierte contra las pasiones destructivas y aguarda una liberación futura." },
  "summary.tp-dan.nt": { fp: "1vlbymb", text: "Su oposición entre verdad y mentira y su advertencia contra la ira hacen eco de la ética neotestamentaria (Efesios 4:25–31)." },
  "summary.tp-dan.significance": { fp: "zuy12y", text: "Deja al descubierto la ira y la falsedad como herramientas del «espíritu de engaño», y recomienda la verdad y el amor." },
  "summary.tp-gad.authorship": { fp: "1dg6y0w", text: "De los Testamentos de los Doce Patriarcas (judíos, con edición cristiana)." },
  "summary.tp-gad.contents": { fp: "3un4b", text: "Gad confiesa su odio hacia José y advierte contra el poder destructivo del odio, y recomienda el amor y el perdón." },
  "summary.tp-gad.context": { fp: "1o3lh4", text: "Aborda el odio dentro de la forma del testamento patriarcal." },
  "summary.tp-gad.nt": { fp: "1tfj5m7", text: "Su contraste entre odio y amor corre muy en paralelo con la enseñanza de 1 Juan de que es el amor, y no el odio, lo que marca a los hijos de Dios." },
  "summary.tp-gad.significance": { fp: "1uwlh14", text: "Retrata el odio como espiritualmente mortal y el amor como su remedio." },
  "summary.tp-issachar.authorship": { fp: "1dg6y0w", text: "De los Testamentos de los Doce Patriarcas (judíos, con edición cristiana)." },
  "summary.tp-issachar.contents": { fp: "atnslc", text: "Isacar recomienda la virtud de la «sencillez de corazón» y una simplicidad de vida honesta y generosa." },
  "summary.tp-issachar.context": { fp: "1tx4f8i", text: "Idealiza la vida agraria sencilla como escuela de virtud." },
  "summary.tp-issachar.nt": { fp: "uomp75", text: "Su elogio de un corazón «sencillo» (sincero) resuena con la enseñanza de Jesús sobre el ojo sano y la entrega sin doblez (Mateo 6)." },
  "summary.tp-issachar.significance": { fp: "13nt3ai", text: "Enseña la integridad, el contentamiento y la generosidad como fruto de un corazón indiviso." },
  "summary.tp-joseph.authorship": { fp: "1dg6y0w", text: "De los Testamentos de los Doce Patriarcas (judíos, con edición cristiana)." },
  "summary.tp-joseph.contents": { fp: "1xnz85k", text: "José relata cómo soportó la tentación y el sufrimiento, y se presenta como modelo de castidad y de perdón paciente." },
  "summary.tp-joseph.context": { fp: "1kagvz2", text: "Presenta a José como modelo de virtud probada." },
  "summary.tp-joseph.nt": { fp: "1puf2wu", text: "Su retrato del justo que sufre, perdona y es exaltado hace eco de la presentación neotestamentaria de Cristo y de su llamado a perseverar y perdonar." },
  "summary.tp-joseph.significance": { fp: "1f4ue6u", text: "Recomienda la castidad, la paciencia en la prueba y el perdón hacia los perseguidores." },
  "summary.tp-judah.authorship": { fp: "1dg6y0w", text: "De los Testamentos de los Doce Patriarcas (judíos, con edición cristiana)." },
  "summary.tp-judah.contents": { fp: "6pv5hq", text: "Judá advierte contra los peligros gemelos del vino y del pecado sexual y contra el amor al dinero, mientras anuncia una realeza que surgirá de su linaje." },
  "summary.tp-judah.context": { fp: "75dt99", text: "Combina la advertencia ética con una esperanza centrada en la tribu real de Judá." },
  "summary.tp-judah.nt": { fp: "blxisc", text: "Su expectativa mesiánica regia desde Judá concuerda con el «León de la tribu de Judá» del Nuevo Testamento (Apocalipsis 5) y con la esperanza davídica." },
  "summary.tp-judah.significance": { fp: "1m4v41d", text: "Une el dominio propio sobrio con la esperanza de un rey venidero de Judá." },
  "summary.tp-levi.authorship": { fp: "1dg6y0w", text: "De los Testamentos de los Doce Patriarcas (judíos, con edición cristiana)." },
  "summary.tp-levi.contents": { fp: "96j0lj", text: "Leví relata las visiones de su elevación al sacerdocio e instruye a sus hijos en la sabiduría, la justicia y el futuro del linaje sacerdotal." },
  "summary.tp-levi.context": { fp: "3f7el1", text: "Refleja un interés marcado por el sacerdocio y su futuro, y se apoya en las tradiciones de Leví." },
  "summary.tp-levi.nt": { fp: "1xwwk8i", text: "Su expectativa de un sacerdote ideal complementa la presentación neotestamentaria del sacerdocio de Cristo en Hebreos." },
  "summary.tp-levi.significance": { fp: "1bxzzvp", text: "Exalta el sacerdocio como cauce de bendición y aguarda una figura sacerdotal venidera." },
  "summary.tp-naphtali.authorship": { fp: "1dg6y0w", text: "De los Testamentos de los Doce Patriarcas (judíos, con edición cristiana)." },
  "summary.tp-naphtali.contents": { fp: "40mvij", text: "Neftalí enseña sobre el buen orden de la naturaleza y llama a una vida vivida en armonía con el designio de Dios." },
  "summary.tp-naphtali.context": { fp: "3cqzk5", text: "Funda la ética en el orden de la creación." },
  "summary.tp-naphtali.nt": { fp: "16gpm6c", text: "Su apelación al orden creado como norma moral corre en paralelo con aspectos del argumento de Pablo en Romanos 1." },
  "summary.tp-naphtali.significance": { fp: "gwz9n4", text: "Recomienda vivir conforme al orden creado que Dios ha establecido." },
  "summary.tp-reuben.authorship": { fp: "1ohuzax", text: "Uno de los Testamentos de los Doce Patriarcas, discursos de despedida atribuidos a los hijos de Jacob; de origen judío (hacia el siglo II a. C.) con edición cristiana posterior." },
  "summary.tp-reuben.contents": { fp: "1hbp5hl", text: "La confesión de Rubén en su lecho de muerte por su pecado con Bilha, con una advertencia a sus descendientes contra los «espíritus de engaño» y las tentaciones de la lujuria." },
  "summary.tp-reuben.context": { fp: "1rvpijb", text: "Los Testamentos adaptan la forma de la bendición en el lecho de muerte para transmitir enseñanza ética y escatológica a las generaciones posteriores." },
  "summary.tp-reuben.nt": { fp: "1o3ysxy", text: "Su psicología de los «dos espíritus» y su enseñanza sobre vicios y virtudes corren en paralelo con la exhortación neotestamentaria sobre la carne, el Espíritu y la pureza sexual." },
  "summary.tp-reuben.significance": { fp: "5lm96u", text: "Enseña la vigilancia frente a las pasiones y el poder del arrepentimiento y del dominio propio." },
  "summary.tp-simeon.authorship": { fp: "1dg6y0w", text: "De los Testamentos de los Doce Patriarcas (judíos, con edición cristiana)." },
  "summary.tp-simeon.contents": { fp: "rgs4gk", text: "Simeón advierte contra la envidia, y recuerda sus celos de José, y urge a una bondad sin dobleces." },
  "summary.tp-simeon.context": { fp: "1tku599", text: "Parte de una colección de discursos patriarcales de despedida usados para la instrucción moral." },
  "summary.tp-simeon.nt": { fp: "1v77o8u", text: "Su advertencia contra la envidia y su llamado al amor fraterno hacen eco de las listas de vicios y de las exhortaciones neotestamentarias (p. ej., Santiago 3–4; 1 Pedro 2:1)." },
  "summary.tp-simeon.significance": { fp: "74ubws", text: "Deja al descubierto la envidia como pasión corrosiva y recomienda la integridad y el amor." },
  "summary.tp-zebulun.authorship": { fp: "1dg6y0w", text: "De los Testamentos de los Doce Patriarcas (judíos, con edición cristiana)." },
  "summary.tp-zebulun.contents": { fp: "okmorh", text: "Zabulón urge a la compasión y a la misericordia hacia todas las personas, y recuerda su lástima por José." },
  "summary.tp-zebulun.context": { fp: "1gqk128", text: "Subraya la compasión dentro del género del testamento patriarcal." },
  "summary.tp-zebulun.nt": { fp: "mssqwv", text: "Su llamado a la misericordia y a la compasión corre en paralelo con el énfasis evangélico en la misericordia (Mateo 5; Lucas 6)." },
  "summary.tp-zebulun.significance": { fp: "152htau", text: "Presenta la misericordia y el amor práctico como centrales en una vida piadosa." },
}
